        public HTML()
        {
            if (HttpContext.Current != null)
            {
                httpContext = HttpContext.Current;
                string str_host_name = HttpContext.Current.Request.ServerVariables["HTTP_HOST"];
                HostName = str_host_name;
                var xCustomHeader = HttpContext.Current.Request.Headers["x-custom-header"];
                ServerRoot = GetServerRoot();//HttpContext.Current.Request.Url.GetLeftPart(UriPartial.Authority);
                if (xCustomHeader != null && xCustomHeader.ToString() != "")
                {
                    dynamic xobj = JsonConvert.DeserializeObject(xCustomHeader);
                    UserID = xobj.UserID;
                    UserName = xobj.UserName;
                    SystemID = xobj.SystemID;
                    WarehouseID = xobj.WarehouseID;
                    UserFullName = xobj.UserFullName;
                    UserPosition = xobj.UserPosition;
                    DomainID = xobj.DomainID;
                    CookieStore.SetCookie("UserID", UserID, TimeSpan.FromDays(30));
                    CookieStore.SetCookie("UserName", UserName, TimeSpan.FromDays(30));
                    SystemLogo = "../Uploads/WarehouseLogo/" + xobj.SystemLogo;
                }
                else
                {
                    SystemID = "13";
                    WarehouseID = "16";
                    UserID = CookieStore.GetCookie("UserID_" + HostName);
                    UserName = CookieStore.GetCookie("UserName_" + HostName);
                    UserFullName = CookieStore.GetCookie("UserFullName_" + HostName);
                }
                string sql = @"select (STUFF((SELECT ',' + a.Code from dbo.TblAccessDomain a
CROSS APPLY STRING_SPLIT(isnull(a.DomainID,''), ',')
where value = (select DomainID from dbo.TblDomain where DomainName ='" + str_host_name + @"')
ORDER BY a.Code FOR XML PATH('')), 1, 1, '')) DomainID";
                DataSet ds = LoadData(sql);
                if (ds.Tables.Count > 0)
                {
                    if (ds.Tables[0].Rows.Count > 0)
                    {
                        DomainID = ds.Tables[0].Rows[0]["DomainID"].ToString();
                    }
                }
            }
        }
        public string GetLocalIP()
        {
            string localIP = "";
            using (Socket socket = new Socket(AddressFamily.InterNetwork, SocketType.Dgram, 0))
            {
                socket.Connect("8.8.8.8", 65530);
                IPEndPoint endPoint = socket.LocalEndPoint as IPEndPoint;
                string str_host_name = HttpContext.Current.Request.ServerVariables["HTTP_HOST"];
                localIP = "http://" + endPoint.Address.ToString() + "/";
            }
            return localIP;
        }
        public string GetServerRoot()
        {
            var request = HttpContext.Current.Request;
            var uri = request.Url;

            string protocol = uri.Scheme + "://";
            string host = uri.Host;
            string port = (uri.Port != 80 && uri.Port != 443) ? ":" + uri.Port : "";
            string appPath = request.ApplicationPath;

            return appPath == "/" ? protocol + host + port + "/" : protocol + host + port + appPath.TrimEnd('/') + "/";
        }
        public string GetCurrentDate()
        {
            DateTime timeNow = DateTime.Now;
            TimeZoneInfo easternZone = TimeZoneInfo.FindSystemTimeZoneById("SE Asia Standard Time");
            DateTime easternTimeNow = TimeZoneInfo.ConvertTime(timeNow, TimeZoneInfo.Local, easternZone);
            return easternTimeNow.ToString("yyyy/MM/dd HH:mm:ss tt");
        }
        public string DrawAccessDeniedPage()
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine("<div class=\"ui-widget\">");
            sb.AppendLine("<div class=\"ui-state-error ui-corner-all\" style=\"padding: 0 .7em;\">");
            sb.AppendLine("<p><span class=\"ui-icon ui-icon-alert\" style=\"float: left; margin-right: .3em;\"></span>");
            sb.AppendLine("<strong>Alert:</strong> Sorry, you don't have permission for accessing this page. Please contact administrator.</p>");
            sb.AppendLine("</div></div>");
            return sb.ToString();
        }

        public string HtmlDecode(string input)
        {
            if (input != "" && input != null && input != "null")
            {
                string corruptedText = HttpUtility.HtmlDecode(HttpUtility.UrlDecode(input));
                // If there are still extra encodings, replace them manually
                // Decode HTML entities repeatedly until the text is clean
                while (corruptedText.Contains("&amp;"))
                {
                    corruptedText = HttpUtility.HtmlDecode(corruptedText);
                }
                return corruptedText;
            }
            else if (input == null || input == "null")
                return input = "";
            else return input;
        }

