                    sb_script.AppendLine("let dValue = '';\r\nif ($(\"#\" + key).data('select2')){\r\nif ($(\"#\" + key).select2('data')[0]) { if (parentField = $(\"#\" + key).select2('data')[0].parentField) { parentField = $(\"#\" + key).select2('data')[0].parentField; parentId = $(\"#\" + key).select2('data')[0].parentId; dValue = $(\"#\" + key).select2('data')[0].text; if (parentField != '') { Data +=`^${parentField}|${parentId}|TextBox|" + TableName + "|False|False||${JSON.stringify({ UpdatePrefixModule: '', SetPrefixToDbFieldName: '', Prefix: '' })}` } } } }\r\nelse\r\ndValue = $(\"#\" + key).val();");
                    sb_script.AppendLine("if (NewobjChange['Status'] == 'Update') { if (dValue != value.Value) {\r\nif (DescObjChange == '') {\r\nDescObjChange = `Modify: ` + value.Label + ` Changed Value From: ` + value.Value;\r\nDescObjChange += ` To: ` + dValue;\r\n}\r\nelse {\r\nDescObjChange += `, ` + value.Label + ` Changed Value From: ` + value.Value;\r\nDescObjChange += ` To: ` + dValue;\r\n}\r\n}");
                    sb_script.AppendLine("} else if (NewobjChange['Status'] == 'New') {\r\nif (DescObjChange == '')\r\nDescObjChange = `Add New: ` + value.Label + ` ` + dValue;\r\nelse\r\nDescObjChange += `, ` + value.Label + ` ` + dValue;\r\n}");
                    sb_script.AppendLine("});\r\nNewobjChange['Description'] = DescObjChange;");

                    sb_script.AppendLine("$(\"#" + frmID + "\").ajaxSubmit({ url: \"" + ServerRoot + "DoActionData/SaveChange\", ");
                    sb_script.AppendLine("dataType: \"json\",");
                    sb_script.AppendLine("contentType:false,");
                    sb_script.AppendLine("async: false,");
                    sb_script.AppendLine("type: 'POST',");
                    if (Authorization)
                        sb_script.AppendLine("headers: { \"Authorization\": \"Bearer \" + access_Token },");
                    sb_script.AppendLine("data: {");
                    sb_script.AppendLine("Data:Data,");
                    sb_script.AppendLine("FormID:\"" + frmID + "\"");
                    sb_script.AppendLine(",TableName:\"" + MultiTblName + "\"");
                    sb_script.AppendLine(",PrimaryField:\"" + EncryAndDecry.Encryp(PrimaryField) + "\"");
                    sb_script.AppendLine(",PrimaryFieldValue:PrimaryFieldValue");
                    sb_script.AppendLine(",DestinationFile:DestinationFile");
                    sb_script.AppendLine(",objInsertTable:JSON.stringify(objInsertTable)");
                    sb_script.AppendLine(",PrefixFor:'" + PrefixFor + "'");
                    sb_script.AppendLine(",SaveChangeAndDeleteOldDataWhenDrawBtnSave:'" + SaveChangeAndDeleteOldDataWhenDrawBtnSave + "'");
                    sb_script.AppendLine(",UserLogData:JSON.stringify(NewobjChange)");
                    sb_script.AppendLine("},");
                    sb_script.AppendLine("beforeSend: function (xhr) { $(\"button\").attr('disabled', true);");
                    if (Authorization)
                        sb_script.AppendLine("xhr.setRequestHeader('x-custom-header', JSON.stringify(headerPara));");
                    sb_script.AppendLine("},");
                    sb_script.AppendLine("error: function (response, callStatus, errorThrown) {");
                    sb_script.AppendLine("$('button').removeAttr('disabled');");
                    sb_script.AppendLine("DialogSweetAlert(\"error\", response.status + \" \" + response.statusText);");
                    sb_script.AppendLine("},");
                    sb_script.AppendLine("uploadProgress: function (event, position, total, percentComplete) { },");
                    sb_script.AppendLine("success: function(responsetext){");
                    sb_script.AppendLine("$(\"button\").attr('disabled', false);");
                    sb_script.AppendLine("$('button').removeAttr('disabled');");
                    sb_script.AppendLine("$('button').prop('disabled', false);");
                    sb_script.AppendLine("},");
                    sb_script.AppendLine("complete: function (response) { var responsetext = JSON.parse(response.responseText); SaveChangeResponse = $(\"#" + frmID + "\").serializeArray();SaveChangeResponse['Data']=responsetext;");
                    sb_script.AppendLine("$(\"button\").attr('disabled', false);");
                    sb_script.AppendLine("$('button').prop('disabled', false);");
                    sb_script.AppendLine("if (responsetext.Result != 2) { DialogSweetAlert('error', responsetext.Message); return false;}");
                    sb_script.AppendLine("responsetext = responsetext.Message;isSaveChange = true;");
                    sb_script.AppendLine("$(\"#" + frmID + "\").removeClass(\"was-validated\");");
                    if (ISHaveCheckBoxGroup)
                        sb_script.AppendLine(ResetCheckedBoxesGroup);
                    sb_script.AppendLine("DialogSweetAlert('Savesuccess', 'Save Change Successfully.');");
                    if (this.FieldIDFocus != "" && FocusFieldIDAfterReset == "")
                    {
                        sb_script.AppendLine("setTimeout(function(){");
