                        {
                            string[] rf = RestFields.Split(new char[] { ',' });
                            for (int i = 0; i < rf.Length; i++)
                            {
                                sb_script.AppendLine("$(\"#" + rf[i].Trim() + "\").val('');");
                                sb_script.AppendLine("Validator.resetElements($(\"#" + rf[i].Trim() + "\"));");
                            }
                        }
                        else
                        {
                            sb_script.AppendLine("Validator.resetForm();");
                        }
                    }
                    sb_script.AppendLine("isSaveChange=true;");
                    if (SaveChangeAndClose)
                    {
                        sb_script.AppendLine("$(\"#" + BtnCloseDialog + "\").click();");
                    }
                    if (SaveChangeCallbackOnCloseDialog)
                    {
                        if (OnDialogCloseCallbackFunction != "")
                            sb_script.AppendLine(OnDialogCloseCallbackFunction);
