                    sb_script.AppendLine("if(responsetext == \"Data inserted successful.\"){");
                    //sb_script.AppendLine("$(\".jfilestyle\").jfilestyle(\"clear\");");
                    sb_script.AppendLine("RowSeleted = -1; CurrentPage = 1;");
                    sb_script.AppendLine("var KeedDateTimeValue = \"\";");
