                            {
                                sb_script.AppendLine("$(\"#" + rf[i].Trim() + "\").val('');");
                            }
                            //sb_script.AppendLine("}");
                        }
                    }
                    if (SaveChangeCallbackFunction != "")
                    {
                        //sb_script.AppendLine("isSaveChange = false;");
                        sb_script.AppendLine(SaveChangeCallbackFunction);
                    }
                    sb_script.AppendLine("if(OldControlID!= \"\") { ");
                    sb_script.AppendLine("if($(\"#\"+ OldControlID).val()){");
                    sb_script.AppendLine("OldValue = $(\"#\"+ OldControlID).val();");
                    sb_script.AppendLine("}");
                    sb_script.AppendLine("}");
                    sb_script.AppendLine("if(KeedDateTimeValue!=\"\") {");
                    sb_script.AppendLine("$(\"#" + frmID + " .DateTimePicker\").val(KeedDateTimeValue);");
                    sb_script.AppendLine("}");
                    sb_script.AppendLine("}");
                    sb_script.AppendLine("else if(responsetext==\"Data updated successful.\"){");
                    if (DrawBtnSaveChange)
                    {
                        if (SaveChangeCallbackFunction != "")
                        {
                            sb_script.AppendLine(SaveChangeCallbackFunction);
                        }
                    }
                    sb_script.AppendLine("$(\"#" + BtnCloseDialog + "\").click();");
                    sb_script.AppendLine("}");
                    sb_script.AppendLine("}");
                    sb_script.AppendLine("});");

                    sb_script.AppendLine("}");

                    sb_script.AppendLine("$(\"#modal-default\").on('hide.bs.modal', function (e) {");
                    sb_script.AppendLine("setTimeout(function() {");
                    sb_script.AppendLine("$(\"button\").attr('disabled', false);$('button').removeAttr('disabled');");
                    sb_script.AppendLine("$('button').prop('disabled', false);");
                    sb_script.AppendLine("}, 500);");
                    sb_script.AppendLine("if (isSaveChange) {");
                    string S = this.OverrideSearch == "" ? "LoadTableGrid" : this.OverrideSearch.Replace("(1);", "");
                    sb_script.AppendLine(string.Concat("if (typeof ", S, "==\"function\") {"));
                    sb_script.AppendLine(string.Concat(S, "(CurrentPage);}"));
                    sb_script.AppendLine("$(\"input[type='radio']:eq(0)\").click();");
                    sb_script.AppendLine("} });");

                    if (this.HtmlButton.Count > 0)
                    {
                        foreach (MVC.HtmlButton oControl in this.HtmlButton)
                        {
                            sb_script.AppendFormat("var SaveButton = '{0}';", oControl.GetHtml());
                            sb_script.AppendLine("$(function(){");
                            string ButtonID = "RemoveAllList";
                            if (oControl.ButtonID != "")
                            {
                                ButtonID = oControl.ButtonID;
                            }
                            sb_script.AppendLine(string.Concat("$(\"#", ButtonID, "\").button({"));
