                            sb_script.AppendLine(string.Concat("$(\"#", ButtonID, "\").click(function(){"));
                            sb_script.AppendLine("});");
                            sb_script.AppendLine("});");
                        }
                    }
                }
            }

            sb_script.AppendLine("</script>");
            sb_frm.AppendLine("</table>");
            sb_frm.AppendLine("</div></div>");
            if (FormID != "")
            {
                if (DrawBtnSaveChange)
