        public string DrawHTMLSearchForm(int Value = 1, string LoadGridFunction = "", bool IsDrawKendoGrid = false,
    string GridTable = "", string kendoGridSetting = "", string GridTable2 = "", string SQL2 = "", string LinkField = "", string JsonData = "")
        {
            ServerRoot = GetServerRoot();
            TableIDToExcel = TblID;

            if (TableName != "" && PrimaryField != "" && FieldName != "")
            {
                DBHelper dBHelper = new DBHelper();
                dBHelper.InitiateConnection();
                var commandStr = @"If not exists (select name from sysobjects where name = '" + TableName + @"')
CREATE TABLE " + TableName + "(" + PrimaryField + " int NOT NULL IDENTITY(1,1) PRIMARY KEY," + FieldName +
                    " nvarchar(50),CreateBy nvarchar(50), CreateDate datetime, SystemID int,WarehouseID int, DomainID  nvarchar(50))";
                SqlCommand command = new SqlCommand(commandStr, dBHelper.sqlConnection);
                command.ExecuteNonQuery();
            }

            StringBuilder sb_frm = new StringBuilder();
            int rnd = new Random().Next(1, 49);

            if (Value != 1)
            {
                return sb_frm.ToString();
            }

            string randomNumber = TblID + "_" + rnd;
            string oID = "CboSearchText";
            if (LoadGridFunction == "") LoadGridFunction = "LoadTableGrid";

            int i;
            bool hasAddControl = false;

            FormID = FormID == "" ? string.Concat("Frm_Search_", randomNumber) : string.Concat(FormID + "_", randomNumber);

            var identity = (ClaimsIdentity)HttpContext.Current.User.Identity;
            string UserID = identity.Claims.Where(c => c.Type == ClaimTypes.Sid).Select(c => c.Value).SingleOrDefault();

            CustomGrid = Value;
            string BunAdd = "";
            var RDName = "SearchText";

            if (AddButton != null && AddButton.ToString() != "")
            {
                BunAdd = AddButton.Replace(" ", "");
                BunAdd = BunAdd.Replace("/", "");
            }

            // ---- breadcrumb ---------------------------------------------------
            // (was written into sb_script; it's a one-off DOM write, not grid
            // behavior, so it stays inline as a tiny script tag right here.)
            if (Caption != null && Caption.ToString() != "")
            {
                sb_frm.AppendLine("<script>$(function(){");
                sb_frm.AppendLine("var TR = '<ul class=\"breadcrumb\">'");
                sb_frm.AppendLine(string.Concat("TR += '<li><a href=\"", ServerRoot, "\">Home</a> <span class=\"divider\">/</span></li>'"));
                sb_frm.AppendLine(string.Concat("TR += '<li class=\"active\">", this.Caption, "</li></ul>'"));
                sb_frm.AppendLine("$(\"#BottomBannerContent\").html(TR);");
                sb_frm.AppendLine("});</script>");
            }

            if (DrawPrintButton && OverridePrint == "")
            {
                sb_frm.AppendLine("<div id=\"dialog-confirm-print\" title=\"Print Option\" style=\"display:none\">");
                sb_frm.AppendLine("<p><span class=\"ui-icon ui-icon-help\" style=\"float:left; margin:0 7px 20px 0;\"></span>");
                sb_frm.AppendLine("Print to excel file?</p>");
                sb_frm.AppendLine("</div>");
            }

            string DivClass = " class=\"row-fluid img-polaroid span12\"";
            if (this.ShowGridOnly) DivClass = "";

            sb_frm.AppendLine("<div id=\"frmSearch" + randomNumber + "\" name=\"frmSearch\"" + DivClass + " style=\"padding:0; margin:0;\">");
            sb_frm.AppendLine(string.Concat("<form onsubmit=\"return false;\" name=\"Frm_Search\" id=\"", FormID, "\" method=\"post\" action=\"\" class=\"form-search\" style=\"padding:0; margin:0;\">"));

            string TblWidth = "width=\"100%\"";
            if (TblAlign.ToLower() != "left" || TblAlign.ToLower() == "auto")
            {
                TblWidth = "";
                TblAlign = TblAlign != "" ? string.Concat("align=\"", TblAlign, "\"") : "";
            }
            else
            {
                TblAlign = "";
            }
            if (TblAlign.ToLower() == "auto") TblWidth = "";

            sb_frm.AppendLine(string.Concat(new[]
            {
                "<table style=\"padding-top:10px;\" border=\"0\" cellspacing=\"0\" cellpadding=\"" + Cellpadding + "\" ",
                TblWidth, " ", this.TblAlign, ">"
            }));

            // ---- date-range controls: render HTML + collect config for the widget ----
            string IsbeweentDate = "";
            var dateRangeSources = new List<DateRangeSource>();

            if (this.HtmlDateTimePickerFromDateToDate.Count > 0)
            {
                foreach (HtmlDateTimePickerFromDateToDate oControl in this.HtmlDateTimePickerFromDateToDate)
                {
                    if (!oControl.DateRangePicker)
                    {
                        dateRangeSources.Add(new DateRangeSource
                        {
                            FromDateID = oControl.FromDateID,
                            ToDateID = oControl.ToDateID,
                            DBField = "",
                            DateRangePicker = false,
                            DateTimePickerWithRanges = oControl.DateTimePickerWithRanges
                        });
                    }
                    else
                    {
                        IsbeweentDate = oControl.DBField;
                        dateRangeSources.Add(new DateRangeSource
                        {
                            FromDateID = oControl.FromDateID,
                            ToDateID = oControl.ToDateID,
                            // matches the original: only the "between" (DBField != "") branch
                            // sends the field name through for the format()/between clause.
                            DBField = IsbeweentDate == "" ? "" : EncryAndDecry.Encryp(oControl.DBField),
                            DateRangePicker = true,
                            DateTimePickerWithRanges = oControl.DateTimePickerWithRanges
                        });
                    }
                    sb_frm.AppendLine(oControl.GetHtml());
                }
            }

            // ---- custom add-controls: render HTML + collect config -----------
            var customFieldSources = new List<CustomFieldSource>();
            if (this.HtmlAddControls.Count > 0)
            {
                hasAddControl = true;
                foreach (HtmlAddControls oControl in this.HtmlAddControls)
                {
                    customFieldSources.Add(new CustomFieldSource { ID = oControl.ID, DBField = EncryAndDecry.Encryp(oControl.DBField) });
                    oControl.LoadGrid_Function = LoadGridFunction;
                    sb_frm.AppendLine(oControl.GetHtml());
                }
            }

            hasAddControl = HtmlRadioBindToComboBox.Count > 0;

            if (ShowSearchButton)
            {
                if (hasAddControl)
                {
                    sb_frm.AppendLine("<tr><td align=\"right\" width=\"150\"><label class=\"col-form-label text-nowrap\" for=\"CboSearchText\" id=\"LblSearchText" + randomNumber + "\"></label></td><td width=\"250\"><div id=\"DivShowSearchText" + randomNumber + "\"></div></td>");
                    sb_frm.AppendLine("<td><button type=\"button\" id=\"" + BunSearch + "\" class=\"" + btnSearchStyle + "\" onclick=\"" + OverrideSearch + "\"><i class=\"ti ti-search\"></i> <span class=\"d-none d-md-inline\">" + SearchText + "</span></button>");
                    if (BunAdd != "" && AllowAdd)
                    {
                        sb_frm.Append("&nbsp;<button type=\"button\" id=\"Bun" + BunAdd + "\" class=\"" + btnSearchStyle + "\"><i class=\"ti ti-library-plus\"></i> <span class=\"d-none d-md-inline\">" + AddButton + "</span></button>");
                    }
                }
                else
                {
                    if (OverrideSearch == "") OverrideSearch = LoadGridFunction + "(1);";
                    // The old code stuck an extra search button (TD<FormID>) after the last
                    // grid column via jQuery once the grid rendered - that DOM tweak is still
                    // handled by TableGridWidget (`!hasAddControl` branch appends TD<FormID>).
                    // We just need the widget to know the button markup, which it already
                    // builds statically from searchButtonId, so nothing else to do here.
                }
            }
            else if (BunAdd != "")
            {
                if (AllowAdd)
                    sb_frm.Append("<tr><td><button type=\"button\" id=\"Bun" + BunAdd + "\" class=\"" + btnSearchStyle + "\"><i class=\"ti ti-library-plus\"></i> <span class=\"d-none d-md-inline\">" + AddButton + "</span></button>");
            }

            if (DrawPrintButton)
            {
                sb_frm.AppendFormat("&nbsp;<button class=\"btn btn-success\" type=\"button\" id=\"PrintButton\" onclick=\"{0}\"><i class=\"fa-thin fa-print\"></i> <span class=\"d-none d-md-inline\">Print</span></button>", this.OverridePrint);
            }
            if (this.DrawSendEmailButton)
            {
                sb_frm.AppendFormat(" <button type=\"button\" id=\"SendEmailButton\" onclick=\"{0}\">&nbsp;</button>", this.OverridePrint);
            }

            string display = this.HtmlRadioBindToComboBox.Count == 1 ? " style=\"display:none\"" : "";
            sb_frm.AppendLine("</td></tr>");

            // ---- radio-driven search fields: render HTML + collect config ----
            var radioOptionSources = new List<RadioOptionSource>();

            if (hasAddControl)
            {
                if (this.ShowSearchButton)
                {
                    sb_frm.AppendLine(string.Concat("<tr", display, "><td>&nbsp;</td><td colspan=\"2\">"));
                    sb_frm.AppendLine("<table border=\"0\" cellspacing=\"0\" cellpadding=\"" + Cellpadding + "\">");
                    sb_frm.AppendLine("<tr>");
                }

                int I = 0;
                if (HtmlRadioBindToComboBox.Count > 0)
                {
                    foreach (RadioOptionBindDataToCbo oControl in this.HtmlRadioBindToComboBox)
                    {
                        if (oControl.ID != "") oID = oControl.ID;
                        I++;
                        if (I == 1) RDName = oControl.ID;

                        radioOptionSources.Add(new RadioOptionSource
                        {
                            ID = oControl.ID,
                            OPTLabel = oControl.OPTLabel,
                            SQL = oControl.SQL,
                            SelectValue = oControl.SelectValue,
                            DisplayField = oControl.DisplayField,
                            ShowAll = oControl.ShowAll.ToString(),
                            Value = oControl.Value,
                            ISAutoComplete = oControl.ISAutoComplete,
                            ISAutoCbo = oControl.ISAutoCbo,
                            Multiple = oControl.Multiple,
                            IsUseConnection2 = oControl.IsUseConnection2.ToString(),
                            ConditionFieldVale = oControl.ConditionFieldVale,
                            placeholder = oControl.placeholder
                        });

                        sb_frm.AppendLine(oControl.GetHtml());
                    }
                }

                if (this.ShowSearchButton)
                {
                    sb_frm.AppendLine("</tr>");
                    sb_frm.AppendLine("</table>");
                    sb_frm.AppendLine("</td></tr>");
                }
            }

            sb_frm.AppendLine("</table>");
            sb_frm.AppendLine("</form>");
            sb_frm.AppendLine("");
            sb_frm.AppendLine(string.Concat("<div id=\"", this.DivTblDataID, "_", randomNumber, "\" name=\"", this.DivTblDataID, "\">"));
            if (ShowGridOnly)
                sb_frm.AppendLine("<div id=\"" + ShowGridTableID + "_" + FormID + "\" name=\"ShowGridTable\" class=\"ShowGridTable\">&nbsp;</div></div>");
            else
                sb_frm.AppendLine("<div id=\"" + ShowGridTableID + "_" + FormID + "\" name=\"ShowGridTable\" class=\"ShowGridTable\" style=\"padding-top:8px;\">&nbsp;</div></div>");

            // ---- GridData / ModifyField: unchanged, still a data contract, not behavior ----
            string GridData = "";
            string ModifyField = "";
            if (this.GH.GridTable != null && this.GH.GridTable.Length > 0)
            {
                GridField[] gridTable = this.GH.GridTable;
                for (i = 0; i < gridTable.Length; i++)
                {
                    GridField GF = gridTable[i];
                    object[] fields = {
                GF.Header, "|", GF.FieldName, "|", GF.TextAlign, "|", GF.IsModifyField, "|", GF.IsGroupByField, "|",
                GF.Colspan, "|", GF.ClassName, "|", GF.IsTotalFooter, "|", GF.TotalLabel, "|", GF.GroupLabel, "|",
                GF.DisplayTextArea, "|", GF.CustomRow, "|", GF.DisplayOneRow, "|", GF.DeleteUseProcedureName, "|",
                GF.Width, "|", GF.IsHiddenField, "|", GF.Link, "|", GF.LinkParameterField, "|", GF.ISTotal, "|",
                GF.NewPage, "|", GF.DataTableNumber, "|", GF.LinkField, "|", GF.DisplayFields, "|", GF.OnOneRow, "|",
                GF.IsExternalLink, "|", GF.ImagePath, "|", GF.IsBorderRight, "|", GF.HideOnPrint, "|",
                GF.TotalGroupFieldName, "|", GF.HideOnPrintTotalFooter, "|", GF.PrintHeader, "|", GF.DisplayTextBox, "|",
                GF.HideDelete, "|", GF.HideEdit, "|" + GF.Style, "|" + GF.isEmail, "|" + GF.isUrl, "|" + GF.Format, "|" +
                GF.EditFunction, "|" + GF.DeleteFunction, "|" + GF.DeleteWithTableName, "|" + GF.DeletedCallBackFunction, "|" +
                GF.DeletePrimaryTblName, "|" + GF.DeletePrimaryFiledName, "|" + GF.DeletePrimaryValue, "|" +
                GF.DeletePrimaryTblNameDependOnTblName + "|" + GF.ActionName + "|" + GF.ActionClickFunction + "|" +
                GF.ActionIcon + "|" + GF.ShowActionNameOnConditionValue + "|" + GF.ShowActionNameOnConditionField + "|" +
                GF.HideEditOnActionNameNotMatch + "|" + GF.HideDeteleOnNotMatch + "|" + GF.DisplayCheckBox + "|" +
                GF.DisplayBarcode + "|" + GF.ExpandableTableFileNameIsNotNull + "|" + GF.ShowOnlyOneImg + "|" + UsingJqueryDataTable
            };
                    GridData = GridData == "" ? string.Concat(fields) : string.Concat(GridData, "^", string.Concat(fields));

                    if (GF.IsModifyField) ModifyField = GF.FieldName;
                }
            }

            // ---- static GridPara params -> StaticFieldWithValue ----------------
            // Original behavior: each GH.GridPara entry contributes "EncryptedName|Value",
            // joined with "^", and used as the base of FieldWithValue<FormID> before the
            // radio/date/custom-field pieces are appended on top of it.
            string staticFieldWithValue = "";
            if (this.GH.GridPara != null && this.GH.GridPara.Length > 0)
            {
                foreach (GridPara GP in this.GH.GridPara)
                {
                    string pair = EncryAndDecry.Encryp(GP.ParaName) + "|" + GP.Value;
                    staticFieldWithValue = staticFieldWithValue == "" ? pair : staticFieldWithValue + "^" + pair;
                }
            }

            // ---- build the config object and hand off to the widget ------------
            var scriptParams = new ScriptBlockParams
            {
                Encrypt = EncryAndDecry.Encryp,

                FormID = FormID,
                TblID = TblID,
                ServerRoot = ServerRoot,
                LoadGridFunction = LoadGridFunction,
                OverrideSearch = OverrideSearch,
                ShowGridTableID = ShowGridTableID,
                BunSearch = BunSearch,
                SearchInputId = oID,
                AddButton = AddButton,
                AddURL = AddURL,
                AddFunctionName = (AddURL == "" && AddFUNCTION != "") ? this.addFUNCTION : null,
                AllowAdd = AllowAdd,
                AllowEdit = AllowEdit,
                AllowDelete = AllowDelete,
                DialogBoxWidth = DialogBoxWidth,
                DialogBoxHeight = DialogBoxHeight.ToString(),
                ModalWidth = ModalWidth,
                ModalHeight = ModalHeight,
                OnDialogCloseCallbackFunction = OnDialogCloseCallbackFunction,
                DrawPrintButton = DrawPrintButton,
                ShowPrintOnTopTable = ShowPrintOnTopTable,
                DrawSendEmailButton = DrawSendEmailButton,
                OverridePrint = OverridePrint,

                GH_SQL = GH.SQL,
                GH_GridProcedureName = GH.GridProcedureName,
                GridData = GridData,
                ModifyField = ModifyField,
                TableName = TableName,
                PrimaryField = PrimaryField,

                UserID = UserID,
                SystemID = SystemID.ToString(),
                WarehouseID = WarehouseID.ToString(),
                DomainID = DomainID,

                IsDrawKendoGrid = IsDrawKendoGrid,
                GridTable = GridTable,
                KendoGridSetting = kendoGridSetting,
                GridTable2 = GridTable2,
                SQL2 = SQL2,
                LinkField = LinkField,
                JsonData = JsonData,

                ShowSearchBox = ShowSearchBox,
                SearchBoxWithColumnName = SearchBoxWithColumnName,
                PageSize = 30,

                ReportTitle = ReportTitle,
                GridHeight = GridHeight,
                OrderBy = OrderBy,
                IsUseHavingCondition = IsUseHavingCondition,
                IsHaveWhereCondition = IsHaveWhereCondition,
                dataTableNumber = dataTableNumber,
                IsFixedTableHeader = IsFixedTableHeader,
                TableClassName = IsFixedTableHeader ? "table mytable-bordered" : TableClassName,
                ShowPaging = ShowPaging,
                NotShowWithNoRecord = NotShowWithNoRecord,
                DrawTotalHeaderTbl = DrawTotalHeaderTbl,
                DrawTotalAllHeader = DrawTotalAllHeader,
                DrawTotalAllFooter = DrawTotalAllFooter,
                DrawTotalAllHeaderDataTableNumber = DrawTotalAllHeaderDataTableNumber,
                DrawTotalAllFooterDataTableNumber = DrawTotalAllFooterDataTableNumber,
                GridUseConnection2 = GridUseConnection2,
                FooterSummaryDataTable = FooterSummaryDataTable,
                LinkSummaryField = LinkSummaryField,
                LinkSummaryColumn = LinkSummaryColumn,
                PrintHeader = PrintHeader,
                PrintFooter = PrintFooter,
                HideOnPrintTotalFooter = HideOnPrintTotalFooter,
                EmailSubject = EmailSubject,
                SendEmailType = SendEmailType,
                JqueryDataTable = JqueryDataTable,
                UsingJqueryDataTable = UsingJqueryDataTable,
                JqueryDataTableResponsive = JqueryDataTableResponsive,
                IsShowJqueryDataTablePrint = IsShowJqueryDataTablePrint,
                HiddenJqueryDataColumns = HiddenJqueryDataColumns,
                PageRecord = PageRecord,
                GridEventClick = GridEventClick,
                GridEventDblClick = GridEventDblClick,
                ShowTblTitle = ShowTblTitle,
                isShowLoadingGrid = isShowLoadingGrid,
                DefaultSearch = DefaultSearch,
                ShowGridOnly = ShowGridOnly,
                ShowSearchButton = ShowSearchButton,
                Caption = Caption,
                TableIDToExcel = TableIDToExcel,
                btnSearchStyle = btnSearchStyle,
                CboSearchStyle = CboSearchStyle,
                CboDataStyle = CboDataStyle,
                rnd = rnd,
                randomNumber = randomNumber,
                StaticFieldWithValue = staticFieldWithValue,

                RadioOptions = radioOptionSources,
                CustomFields = customFieldSources,
                DateRanges = dateRangeSources
            };

            string scriptBlock = MVC.DrawHTMLSearchForm.BuildScriptBlock(scriptParams);
            sb_frm.AppendLine(scriptBlock);

            return sb_frm.ToString();
        }

        public string DataTableToJSONWithJavaScriptSerializer(DataTable table)
        {
            JavaScriptSerializer jsSerializer = new JavaScriptSerializer();
            List<Dictionary<string, object>> parentRow = new List<Dictionary<string, object>>();
            Dictionary<string, object> childRow;
            foreach (DataRow row in table.Rows)
            {
                childRow = new Dictionary<string, object>();
                foreach (DataColumn col in table.Columns)
                {
                    childRow.Add(col.ColumnName, row[col]);
                }
                parentRow.Add(childRow);
            }
            return jsSerializer.Serialize(parentRow);
        }

        public string DrawKendoGrid(string JsonDatas = "", DataSet dataSet = null, string GridData = "", string kendoGridSetting = "", GridProperty gridProperty = null, string GridData2 = "", DataSet dataSet2 = null, string LinkField = "", string FieldWithValue = "", string SystemID = "", string WarehouseID = "", string DomainID = "")
        {
            HTML html = new HTML();
            GridField[] gridTable = null, gridTable2 = null;
            KendoGridSetting kendoGridSettings = null;
            string RDN = GetUnixEpochMethod(DateTime.Now).ToString("0000");
            string SqlData = "", SqlData2 = "";
            string LoadGridFunction = "", EditURL = "";

            if (!string.IsNullOrEmpty(kendoGridSetting))
            {
                kendoGridSettings = JsonConvert.DeserializeObject<KendoGridSetting>(kendoGridSetting);
                GroupableKendoGrid = kendoGridSettings.groupable;
                FilterableKendoGrid = kendoGridSettings.filterable;
                KendoGridColumnMenu = kendoGridSettings.columnMenu;
                ShowToolbarKendoGrid = kendoGridSettings.ShowToolbarKendoGrid;
                KendoGridAutoFitColumn = kendoGridSettings.KendoGridAutoFitColumn;
                GridEventClick = kendoGridSettings.GridEventClick;
                KendoGridStickyColumn = kendoGridSettings.KendoGridStickyColumn;
                KendoGridShowCheckbox = kendoGridSettings.KendoGridShowCheckbox;
            }

            if (gridProperty != null)
            {
                AllowEdit = gridProperty.AllowEdit;
                AllowDelete = gridProperty.AllowDelete;
                AddURL = gridProperty.EditURL;
                DialogBoxWidth = gridProperty.DialogBoxWidth;
                DialogBoxHeight = int.TryParse(gridProperty.DialogBoxHeight, out int id) ? id : 0;
                ServerRoot = gridProperty.ServerRoot;
                FormID = gridProperty.FormID;
                TableName = gridProperty.TableName;
                OnDialogCloseCallbackFunction = gridProperty.OnDialogCloseCallbackFunction;
                LoadGridFunction = gridProperty.LoadGridFunction;
                EditURL = gridProperty.EditURL;
                TblID = gridProperty.TblID;
            }
            if (JsonDatas == "")
            {
                if (GH.SQL != "")
                {
                    gridTable = GH.GridTable;
                    SqlData = JsonConvert.SerializeObject(JsonData(GH.SQL));
                }
                else
                {
                    if (kendoGridSettings == null || !kendoGridSettings.ServerPaging)
                        SqlData = JsonConvert.SerializeObject(dataSet.Tables[0]).ToJsonString();
                }
            }
            else
                SqlData = JsonDatas;
            if (GridData2 != "")
                gridTable2 = JsonConvert.DeserializeObject<GridField[]>(GridData2);
            if (dataSet2 != null)
                SqlData2 = JsonConvert.SerializeObject(dataSet2.Tables[0]).ToJsonString();
            if (GridData != "")
                gridTable = JsonConvert.DeserializeObject<GridField[]>(GridData);

            // ── Precompute anything that genuinely needs server-side C# logic ──────
            // (encryption, barcode markup) — everything else is handled in JS now.
            if (gridTable != null)
            {
                foreach (var col in gridTable)
                {
                    col.DeleteWithTableNameEncrypted = string.IsNullOrEmpty(col.DeleteWithTableName)
                        ? "" : EncryAndDecry.Encryp(col.DeleteWithTableName);
                    if (col.DisplayBarcode)
                        col.RawBarcodeTemplate = GenerateBarcode("#=" + col.FieldName + "#");
                }
            }
            if (gridTable2 != null)
            {
                foreach (var col in gridTable2)
                {
                    col.DeleteWithTableNameEncrypted = string.IsNullOrEmpty(col.DeleteWithTableName)
                        ? "" : EncryAndDecry.Encryp(col.DeleteWithTableName);
                    if (col.DisplayBarcode)
                        col.RawBarcodeTemplate = GenerateBarcode("#=" + col.FieldName + "#");
                }
            }

            var editableFieldsObj = new Dictionary<string, object>();
            string editableFieldPrimaryId = "";
            if (kendoGridSettings != null && kendoGridSettings.IsEditable && gridTable != null)
            {
                foreach (var col in gridTable)
                {
                    if (col.PrimaryKeyFieldName) editableFieldPrimaryId = col.FieldName;
                    var fieldConfig = new Dictionary<string, object> { ["editable"] = col.Editable };
                    if (col.Type == "number")
                    {
                        fieldConfig["type"] = "number";
                        fieldConfig["validation"] = new { required = true, min = 0 };
                    }
                    else if (col.Type == "boolean")
                        fieldConfig["type"] = "boolean";
                    else
                        fieldConfig["validation"] = new { required = true };
                    editableFieldsObj[col.FieldName] = fieldConfig;
                }
            }

            bool manualHeaderExcel = kendoGridSettings != null
                && KendoGridExportExcelByManualCode
                && !kendoGridSettings.KendoTreeList
                && kendoGridSettings.ShowHeaderInfoExcel;

            object detail = null;
            if (GridData2 != "")
            {
                detail = new
                {
                    linkField = EncryAndDecry.Decryp(LinkField),
                    procedureName2 = kendoGridSettings?.ProcedureName2 ?? "",
                    procedureName2Encrypted = string.IsNullOrEmpty(kendoGridSettings?.ProcedureName2)
                        ? "" : EncryAndDecry.Encryp(kendoGridSettings.ProcedureName2),
                    urlApiGetDetail = kendoGridSettings?.UrlApiGetDetail ?? "",
                    columns = gridTable2,
                    data = string.IsNullOrEmpty(SqlData2) ? JsonConvert.DeserializeObject(SqlData) : JsonConvert.DeserializeObject(SqlData2)
                };
            }

            var config = new
            {
                rdn = RDN,
                tblId = TblID,
                isTreeList = kendoGridSettings?.KendoTreeList ?? false,
                groupable = GroupableKendoGrid,
                filterable = FilterableKendoGrid,
                columnMenu = KendoGridColumnMenu,
                pageable = PageableKendoGrid,
                height = GridHeight,
                autoFitColumn = KendoGridAutoFitColumn,
                showCheckbox = KendoGridShowCheckbox,
                showToolbar = ShowToolbarKendoGrid,
                reportTitle = ReportTitle,
                headerReportNameExcel = kendoGridSettings?.HeaderReportNameExcel ?? "",
                manualHeaderExcel,
                showPrintDate = kendoGridSettings?.ShowPrintDate,
                showFilterDateRange = kendoGridSettings?.ShowFilterDateRange,
                serverRoot = ServerRoot,
                tableName = TableName,
                allowEdit = AllowEdit,
                allowDelete = AllowDelete,
                editUrl = EditURL,
                dialogBoxWidth = DialogBoxWidth,
                dialogBoxHeight = DialogBoxHeight,
                onDialogCloseCallbackFunction = OnDialogCloseCallbackFunction,
                formId = FormID,
                loadGridFunction = LoadGridFunction,
                deletedCallBackFunction = gridTable != null && gridTable.Length > 0 ? gridTable[0].DeletedCallBackFunction : "",
                deleteDefaultFieldNameEncrypted = gridTable != null && gridTable.Length > 0
                    ? EncryAndDecry.Encryp(gridTable[0].FieldName) : "",
                isEditable = kendoGridSettings?.IsEditable ?? false,
                showBellButton = kendoGridSettings?.ShowBellButton ?? false,
                onClickBellButton = kendoGridSettings?.OnClickBellButton ?? "",
                serverPaging = kendoGridSettings?.ServerPaging ?? false,
                urlApiGetData = kendoGridSettings?.UrlApiGetData ?? "",
                urlApiUpdateData = kendoGridSettings?.UrlApiUpdateData ?? "",
                procedureNameEncrypted = kendoGridSettings != null
                    ? EncryAndDecry.Encryp(kendoGridSettings.IsRawSql ? kendoGridSettings.SQLQuery : kendoGridSettings.ProcedureName) : "",
                fieldWithValue = FieldWithValue,
                isRawSql = kendoGridSettings?.IsRawSql,
                enablePaging = kendoGridSettings?.EnablePaging,
                orderBy = kendoGridSettings?.OrderBy,
                systemId = SystemID,
                warehouseId = WarehouseID,
                domainId = DomainID,
                pageSize = 30,
                gridEventClick = GridEventClick,
                hasKendoGridSetting = !string.IsNullOrEmpty(kendoGridSetting),
                editableFieldPrimaryId,
                editableFields = editableFieldsObj,
                data = (kendoGridSettings == null || !kendoGridSettings.ServerPaging) && !string.IsNullOrEmpty(SqlData)
                    ? JsonConvert.DeserializeObject(SqlData) : null,
                columns = gridTable,
                detail
            };

            var sb = new StringBuilder();
            sb.AppendLine("<div id=\"" + TblID + "\"></div>");
            sb.AppendLine("<script>");
            sb.AppendLine("$(function(){ initKendoGrid(" + JsonConvert.SerializeObject(config,
                new JsonSerializerSettings { ContractResolver = new Newtonsoft.Json.Serialization.CamelCasePropertyNamesContractResolver() }) + "); });");
            sb.AppendLine("</script>");

            if (GridEventClick != "")
            {
                sb.AppendLine("<style>");
                sb.AppendLine("#" + TblID + " tbody tr:hover { cursor:pointer; }");
                sb.AppendLine("</style>");
            }
            if (GridData2 != "")
            {
                sb.AppendLine(@"<script type=""text/x-kendo-template"" id=""template"">
                    <div class=""detailTabstrip"">
                    <div class=""orders""></div>
                    </div>
                </script>");
            }

            return sb.ToString();
        }

