                    for (int k = 0; k < strco.Length; k++)
                    {
                        string target = strco[k];
                        sb.Append("{ target: " + target + ", visible: false },");
                    }
                    sb.AppendLine("],");
                }
                sb.AppendLine("\"responsive\": " + JqueryDataTableResponsive.ToString().ToLower() + ",");
                sb.AppendLine("lengthMenu: [\r\n[" + PageRecord + ", 50, 100, -1 ],\r\n['" + PageRecord + "', '50', '100', 'Show all' ]\r\n],");
                sb.AppendLine("\"lengthChange\": true, \"paging\": true,");
                sb.AppendLine("\"language\": {");
                sb.AppendLine("\"emptyTable\": \"No items to display.\",");
                sb.AppendLine("\"info\": \"Showing _START_ to _END_ of _TOTAL_ entries\",");
                sb.AppendLine("\"infoEmpty\": \"Showing 0 to 0 of 0 entries\",");
                sb.AppendLine("searchPlaceholder: \"Search\"");
                sb.AppendLine("},");
                if (IsShowJqueryDataTablePrint)
                {
                    sb.AppendLine("dom: \"<'row'<'col-sm-12 col-md-6 d-flex align-items-center justify-content-start'f><'col-sm-12 col-md-6 d-flex align-items-center justify-content-end'B>>\" +\r\n\"<'row'<'col-sm-12'tr>>\" +\r\n\"<'row'<'col-sm-12 col-md-5'i><'col-sm-12 col-md-7'p>>\",");
                    sb.AppendLine("buttons: ['pageLength',");
                    sb.AppendLine("{extend: 'colvis', text: 'Column visibility', exportOptions: {columns: ':visible'}},");//Column visibility
                    sb.AppendLine("{");
                    sb.AppendLine("extend: 'excelHtml5',");
                    sb.AppendLine("text: '<i class=\"fa-regular fa-file-excel\"></i> <span class=\"d-none d-md-inline\">Excel</span>',");
                    sb.AppendLine("titleAttr: 'Generate Excel',");
                    sb.AppendLine("className: 'btn btn-primary btn-sm'");
                    sb.AppendLine("},");
                    sb.AppendLine("{");
                    sb.AppendLine("extend: 'csvHtml5',");
                    sb.AppendLine("text: '<i class=\"fa-solid fa-file-csv\"></i> <span class=\"d-none d-md-inline\">CSV</span>',");
                    sb.AppendLine("titleAttr: 'Generate CSV',");
                    sb.AppendLine("className: 'btn btn-info btn-sm'");
                    sb.AppendLine("},");
                    sb.AppendLine("{");
                    sb.AppendLine("extend: 'copyHtml5',");
                    sb.AppendLine("text: '<i class=\"fa fa-copy\"></i> <span class=\"d-none d-md-inline\">Copy</span>',");
                    sb.AppendLine("titleAttr: 'Copy to clipboard',");
                    sb.AppendLine("className: 'btn btn-primary btn-sm'");
                    sb.AppendLine("},");
                    sb.AppendLine("{");
                    sb.AppendLine("extend: 'print',");
                    sb.AppendLine("exportOptions: { columns: ':visible'},");
                    sb.AppendLine("text: '<i class=\"ti ti-printer\"></i><span class=\"d-none d-md-inline\">Print</span>',");
                    sb.AppendLine("titleAttr: 'Print Table',");
                    sb.AppendLine("className: 'btn btn-default btn-sm'");
                    sb.AppendLine("}");
                    sb.AppendLine("]");
                }
                sb.AppendLine("})");
                sb.AppendLine("var row='';");
                sb.AppendLine("row+='<div class=\"form-group\"><div class=\"input-group\">'");
                sb.AppendLine("row+='<div class=\"input-group-prepend\"><label for=\"myInputSearch\" class=\"input-group-text\"><i class=\"fas fa-search\"></i></label></div>'");
                sb.AppendLine("row+='<input id=\"myInputSearch\" type=\"search\" class=\"form-control\" placeholder=\"Search\" />';");
                sb.AppendLine("row+='</div></div>'");
                sb.AppendLine("$(\"#TableGride_filter\").html(row);");
                sb.AppendLine("$(\"#TableGride_filter\").removeClass(\"dataTables_filter\");");
                sb.AppendLine("$('#myInputSearch').on('keyup', function () {");
                sb.AppendLine("MyDataTable.search(this.value).draw();");
                sb.AppendLine("});");
                sb.AppendLine("$(\"div.dt-buttons\").addClass('btn-group flex-wrap');");
                sb.AppendLine("$(\"div.btn-group\").removeClass('dt-buttons');");
                sb.AppendLine("}, 100);");
            }
            sb.AppendLine("});</script>");
            return sb.ToString();
        }

        public string DrawHtmlTableRow(DataTable dataTable)
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine("<table class=\"" + TableClassName + "\" width=\"100%\" cellspacing=\"0\" cellpadding=\"" + Cellpadding + "\" border=\"0\">");
            //sb.AppendLine("<thead><tr class=\"header\">");
            GridField[] gridTable = GH.GridTable;
            if (gridTable != null)
            {
                for (int i = 0; i < gridTable.Length; i++)
                {
                    GridField GH = gridTable[i];
                    sb.AppendLine("<th>" + GH.Header + "</th>");
                }
                sb.AppendLine("</tr></thead>");
                sb.AppendLine("<tbody>");
                foreach (DataRow dr in dataTable.Rows)
                {
                    sb.AppendLine("<tr name=\"TrRowNo\">");
                    for (int i = 0; i < gridTable.Length; i++)
                    {
                        GridField GF = gridTable[i];
                        sb.AppendLine("<td" + (GF.TextAlign != "" ? " align=\"" + GF.TextAlign + "\"" : "") + ">" + dr[GF.FieldName] + "</td>");
                    }
                    sb.AppendLine("</tr>");
                }
                sb.AppendLine("</tbody></table>");
            }
            else
            {
                int j = 0;
                //if (dataTable.Columns[0].ColumnName != "No")
                //{
                //    sb.AppendLine("<th>No</th>");
                //}
                //foreach (DataColumn dc in dataTable.Columns)
                //{
                //    string HeaderName = dc.ColumnName;
                //    sb.AppendLine("<th>" + HeaderName + "</th>");
                //}
                //sb.AppendLine("</tr></thead>");
                sb.AppendLine("<tbody>");
                foreach (DataRow dr in dataTable.Rows)
                {
                    j++;
                    sb.AppendLine("<tr name=\"TrRowNo\">");
                    //sb.AppendLine("<td>" + j + "</td>");
                    foreach (DataColumn dc in dataTable.Columns)
                    {
                        sb.AppendLine("<td>" + dr[dc.ColumnName] + "</td>");
                    }
                    sb.AppendLine("</tr>");
                }
                sb.AppendLine("</tbody></table>");
            }
            return sb.ToString();
        }
