        public CsvWriterOptions GetCsvOptions(char separator, CultureInfo culture = null)
        {
            return new CsvWriterOptions
            {
                Separator = separator,
                FormatProvider = culture ?? CultureInfo.InvariantCulture
            };
        }

        // 1. JSON to CSV
        public string JsonToCsv(string jsonContent, string delimiter)
        {
            var data = JArray.Parse(jsonContent);

            using (var writer = new StringWriter())
            using (var csv = CsvWriter.Create(
                writer,
                GetCsvOptions(delimiter[0], CultureInfo.CurrentCulture)))
            {
                if (data.Count == 0)
                    return writer.ToString();

                var headers = ((JObject)data[0]).Properties()
                    .Select(x => x.Name)
                    .ToArray();

                csv.WriteRecord(headers);

                foreach (JObject item in data)
                {
                    foreach (var header in headers)
                    {
                        var value = item[header];

                        csv.WriteField(value == null || value.Type == JTokenType.Null
                            ? null
                            : value.Type == JTokenType.String
                                ? value.Value<string>()
                                : value.ToString(Newtonsoft.Json.Formatting.None));
                    }

                    csv.EndRecord();
                }

                return writer.ToString();
            }
        }

        // 2. DataSet to CSV
        public string JsonToCsv(DataSet ds)
        {
            using (var writer = new StringWriter())
            using (var csv = CsvWriter.Create(writer, GetCsvOptions(',')))
            {
                foreach (DataTable dt in ds.Tables)
                    WriteDataTableToCsv(csv, dt);

                return "\uFEFF" + writer.ToString();
            }
        }

        // 3. DataSet to Custom CSV
        public void JsonToCustomCsv(DataSet ds, string filePath)
        {
            using (var writer = new StreamWriter(
                filePath, false, new UTF8Encoding(true)))
            using (var csv = CsvWriter.Create(writer, GetCsvOptions('|')))
            {
                foreach (DataTable dt in ds.Tables)
                {
                    writer.WriteLine("Operator Name: NSM ISP");
                    WriteDataTableToCsv(csv, dt);
                }
            }
        }

        // Shared DataTable writer
        private void WriteDataTableToCsv(CsvWriter csv, DataTable dt)
        {
            // Write headers
            foreach (DataColumn column in dt.Columns)
                csv.WriteField(column.ColumnName);

            csv.EndRecord();

            // Write rows
            foreach (DataRow row in dt.Rows)
            {
                foreach (var value in row.ItemArray)
                    csv.WriteField(value == DBNull.Value ? null : value);

                csv.EndRecord();
            }
        }

        public void ExportToExcel(string html, string fileName)
        {
            html = html.Replace("&gt;", ">");
            html = html.Replace("&lt;", "<");
            HttpContext.Current.Response.ClearContent();
            HttpContext.Current.Response.AddHeader("content-disposition", "attachment;filename=" + fileName + "_" + DateTime.Now.ToString("M_dd_yyyy_H_M_s") + ".xls");
            HttpContext.Current.Response.ContentType = "application/xls";
            HttpContext.Current.Response.Write(html);
            HttpContext.Current.Response.End();
        }
