                                            Condition += " and " + SearchWithColumnName.Trim();
                                    }
                                }
                            }
                            else if (Condition != "" && !IsSubGrid)
                            {
                                if (FieldName == "between")
                                    Condition += " and " + Value.Trim();
                                else
                                    Condition += " AND isnull(" + FieldName + ",'') = case when '" + Value.Trim() + "' <> '' then N'" + Value.Trim() + "' else isnull(" + FieldName + ",'') end";
                            }
                        }
                    }
                    if (Condition == "" && IsUseHavingCondition && SearchWithColumnName != "")
                        Condition = " Having " + SearchWithColumnName.Trim();
                    else if (Condition == "" && SearchWithColumnName != "")
                        Condition = " and " + SearchWithColumnName.Trim();

                    SQL += " " + Condition;

                    string TotalRecord_SQL = SQL;

                    if (OrderBy == "" && PrimaryField != "")
                        SQL += " ORDER BY " + PrimaryField + "";
                    else if (OrderBy != "")
                        SQL += " ORDER BY " + OrderBy;
                    if (ShowPaging)
                    {
                        if (PageSize != 0)
                        {
                            SQL += " OFFSET " + PageSize + " *(" + Page + " - 1) ROWS ";
                            SQL += "FETCH NEXT " + PageSize + " ROWS ONLY";
                        }
                        SQL += ";select count(*) as TotalRecord from (" + TotalRecord_SQL + ") AS TotalRecord;";
                    }
                    SQL_C.CommandType = CommandType.Text;
                    SQL_C.CommandTimeout = 120;
                    SQL_C.CommandText = SQL;
                    SqlDataAdapter sqlAdapter = new SqlDataAdapter(SQL_C);
                    sqlAdapter.Fill(DS);
                    connection.Close();
                    SQL_C.Connection.Close();
                    SQL_C.Dispose();
                    return DS;
                }
            }
            else
            {
                SqlCommand cm = new SqlCommand();
                string ProcedureName = EncryAndDecry.Decryp(GridProcedureName);
                cm = new SqlCommand(ProcedureName, connection);
                SQL_C.CommandType = CommandType.StoredProcedure;
                cm.CommandType = CommandType.StoredProcedure;
                SqlCommandBuilder.DeriveParameters(cm);
                SQL_C.CommandText = ProcedureName;
                for (int i = 0; i < strArrays.Length; i++)
                {
                    string FName = strArrays[i];
                    if (FName != "")
                    {
                        chrArray = new char[] { '|' };
                        string[] FNWV = FName.Split(chrArray);
                        string FieldName = EncryAndDecry.Decryp(FNWV[0]);
                        string Value = FNWV[1];
                        if (Value == "All")
                        {
                            Value = "";
                        }
                        if (FieldName == "UserID")
                        {
                            ParameterUserID = "@UserID";
                        }
                        if (FieldName == "WarehouseID")
                        {
                            ParameterWarehouseID = "@WarehouseID";
                        }
                        if (FieldName == "SystemID")
                        {
                            ParameterSystemID = "@SystemID";
                        }
                        if (FieldName == "DomainID")
                        {
                            ParameterDomainID = "@DomainID";
                        }
                        SQL_C.Parameters.Add(new SqlParameter(string.Concat("@", FieldName), Value.Trim()));
                    }
                }
                foreach (SqlParameter pm in cm.Parameters)
                {
                    if (pm.ParameterName == "@UserID" && ParameterUserID == "")
                    {
                        SQL_C.Parameters.Add(new SqlParameter("@UserID", HttpContext.Current.Session["UserID"].ToString()));
                    }
                    if (pm.ParameterName == "@SystemID" && ParameterSystemID == "")
                    {
                        SQL_C.Parameters.Add(new SqlParameter("@SystemID", SystemID));
                    }
                    if (pm.ParameterName == "@WarehouseID" && ParameterWarehouseID == "")
                    {
                        SQL_C.Parameters.Add(new SqlParameter("@WarehouseID", WarehouseID));
                    }
                    if (pm.ParameterName == "@DomainID" && ParameterDomainID == "")
                    {
                        SQL_C.Parameters.Add(new SqlParameter("@DomainID", DomainID));
                    }
                    if (!ShowPaging)
                        Page = 0;

                    if (pm.ParameterName == "@Page")
                    {
                        SQL_C.Parameters.Add(new SqlParameter("@Page", Page));
                    }
                    if (pm.ParameterName == "@RecsPerPage")
                    {
                        SQL_C.Parameters.Add(new SqlParameter("@RecsPerPage", PageSize));
                    }
                }
                //DS = fetchDataTable(SQL_C).Result;
                SQL_C.CommandTimeout = 120;
                SqlDataAdapter sqlAdapter = new SqlDataAdapter(SQL_C);
                sqlAdapter.Fill(DS);
                connection.Close();
                SQL_C.Connection.Close();
                SQL_C.Dispose();
                return DS;
            }
        }
        private string HtmlToPlainText(string html)
        {
            const string tagWhiteSpace = @"(>|$)(\W|\n|\r)+<";//matches one or more (white space or line breaks) between '>' and '<'
            const string stripFormatting = @"<[^>]*(>|$)";//match any character between '<' and '>', even when end tag is missing
            const string lineBreak = @"<(br|BR)\s{0,1}\/{0,1}>";//matches: <br>,<br/>,<br />,<BR>,<BR/>,<BR />
            var lineBreakRegex = new Regex(lineBreak, RegexOptions.Multiline);
            var stripFormattingRegex = new Regex(stripFormatting, RegexOptions.Multiline);
            var tagWhiteSpaceRegex = new Regex(tagWhiteSpace, RegexOptions.Multiline);

            var text = html;
            //Decode html specific characters
            text = System.Net.WebUtility.HtmlDecode(text);
            //Remove tag whitespace/line breaks
            text = tagWhiteSpaceRegex.Replace(text, "><");
            //Replace <br /> with line breaks
            text = lineBreakRegex.Replace(text, Environment.NewLine);
            //Strip formatting
            text = stripFormattingRegex.Replace(text, string.Empty);

            return text;
        }
