        public string ToUrlSlug(string value)
        {
            //First to lower case
            value = value.ToUpperInvariant();
            //Remove all accents
            var bytes = Encoding.GetEncoding("Cyrillic").GetBytes(value);
            value = Encoding.ASCII.GetString(bytes);
            //Replace spaces
            value = Regex.Replace(value, @"\s", "-", RegexOptions.Compiled);
            //Remove invalid chars
            value = Regex.Replace(value, @"[^\w\s\p{Pd}]", "", RegexOptions.Compiled);
            //Trim dashes from end
            value = value.Trim('-', '_');
            //Replace double occurences of - or \_
            value = Regex.Replace(value, @"([-_]){2,}", "$1", RegexOptions.Compiled);
            return value;
        }
        /// <summary>
        /// Renaming Files name according to current system time
        /// </summary>
        /// <param name="dateTime"></param>
        /// <returns></returns>
        public double GetUnixEpochMethod(DateTime dateTime)
        {
            var unixTime = dateTime.ToUniversalTime() -
                           new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc);

            return unixTime.TotalSeconds;
        }
        public SqlResult SaveChange(string Data, string FormID, string TableName = "", string DestinationFile = "", string PrimaryField = "", string PrimaryFieldValue = "0", object[] objInsertTable = null, bool SaveChangeAndDeleteOldDataWhenDrawBtnSave = false, object[] UserLogData = null)
        {
            SqlResult result = new SqlResult();
            char[] chrArray = new char[] { '\u005E' };
            string storeFileName = "";
            if (HttpContext.Current.Request.Files.Count > 0)
            {
                string[] strArrays1 = Data.Split(chrArray);
                string[] strdest = DestinationFile.Split('|');
                int j = 0;
                for (int i = 0; i < strArrays1.Length; i++)
                {
                    string DBData = strArrays1[i];
                    chrArray = new char[] { '|' };
                    string[] DBFV = DBData.Split(chrArray);
                    if (DBFV.Length > 2)
                    {
                        if (DBFV[2].ToString().Trim() == "File")
                        {
                            if (DBFV[1].ToString().Trim() != "")
                            {
                                string DestFile = strdest[j];
                                string s = EncryAndDecry.Decryp(DBFV[0].ToString().Trim());
                                string path = HttpContext.Current.Request.PhysicalApplicationPath.ToString() + DestFile;
                                if (!Directory.Exists(path))
                                    Directory.CreateDirectory(path);
                                storeFileName = "";
                                foreach (var file in HttpContext.Current.Request.Files.GetMultiple(s))
                                {
                                    string fName = Guid.NewGuid() + "_" + file.FileName;
                                    if (PrimaryFieldValue != "0")
                                        fName = file.FileName;
                                    string savedFileName = System.IO.Path.Combine(path, fName);
                                    file.SaveAs(savedFileName);
                                    if (storeFileName == "")
                                        storeFileName = fName;
                                    else
                                        storeFileName += "~" + fName;
                                }
                                if (storeFileName != "")
                                    Data = Data.Replace(DBFV[1].ToString().Trim(), storeFileName);
                                j++;
                            }
                        }
                    }
                }
            }
            return SaveChangeForm(HttpUtility.HtmlEncode(Data), FormID, TableName, storeFileName, PrimaryField, PrimaryFieldValue, objInsertTable, SaveChangeAndDeleteOldDataWhenDrawBtnSave, UserLogData);
        }
