        public string DetermineCompName(string IP)
        {
            IPAddress myIP = IPAddress.Parse(IP);
            IPHostEntry GetIPHost = Dns.GetHostEntry(myIP);
            List<string> compName = GetIPHost.HostName.ToString().Split('.').ToList();
            return compName.First();
        }
        public SqlResult SaveChangeData(string SQL, bool ISStoreProcedure = false, Dictionary<string, string> Para = null, bool ExecuteScalar = false, bool ExecuteDataSet = false, string DBConnectionString = "")
        {
            DBHelper dbHelper = new DBHelper();
            if (DBConnectionString != "")
                dbHelper.ConnectionString = DBConnectionString;
            SqlResult Result = new SqlResult();
            dbHelper.InitiateConnection();
            SqlTransaction SQL_T = dbHelper.sqlConnection.BeginTransaction();
            try
            {
                SqlCommand SQL_C = dbHelper.sqlConnection.CreateCommand();
                SQL_C.CommandType = CommandType.Text;
                if (Para != null && Para.Count > 0)
                {
                    if (ISStoreProcedure)
                        SQL_C.CommandType = CommandType.StoredProcedure;
                    SQL_C.CommandText = SQL;
                    foreach (KeyValuePair<string, string> item in Para)
                    {
                        SQL_C.Parameters.Add(new SqlParameter(item.Key, item.Value));
                    }
                }
                else
                {
                    SQL_C.CommandText = SQL;
                }
                SQL_C.Transaction = SQL_T;
                if (ExecuteScalar)
                {
                    if (!ExecuteDataSet)
                        Result.Value = SQL_C.ExecuteScalar().ToString();
                    else
                    {
                        SqlDataAdapter sqlAdapter = new SqlDataAdapter(SQL_C);
                        DataSet ds_data = new DataSet();
                        sqlAdapter.Fill(ds_data);
                        Result.Data = ds_data;
                        sqlAdapter.Dispose();
                        ds_data.Dispose();
                    }
                }
                else
                {
                    SQL_C.ExecuteNonQuery();
                }
                SQL_T.Commit();
                dbHelper.CloseConnection();
                Result.Result = ResultType.Successful;
                Result.Message = "Data save change successful.";
            }
            catch (Exception exception)
            {
                Exception ex = exception;
                SQL_T.Rollback();
                dbHelper.CloseConnection();
                Result.Message = ex.Message;
                Result.Result = ResultType.Failed;
            }
            return Result;
        }
        public SqlResult SaveChangeData(string SQL, bool ISStoreProcedure = false, bool ExecuteScalar = false)
        {
            DBHelper dbHelper = new DBHelper();
            SqlResult Result = new SqlResult();
            try
            {
                dbHelper.InitiateConnection();
                SqlTransaction SQL_T = dbHelper.sqlConnection.BeginTransaction();
                SqlCommand SQL_C = dbHelper.sqlConnection.CreateCommand();
                SQL_C.CommandType = CommandType.Text;
                try
                {
                    SQL_C.CommandText = SQL;
                    SQL_C.Transaction = SQL_T;
                    if (ExecuteScalar)
                    {
                        Result.Value = SQL_C.ExecuteScalar().ToString();
                    }
                    else
                    {
                        SQL_C.ExecuteNonQuery();
                    }
                    SQL_T.Commit();
                    dbHelper.CloseConnection();
                    Result.Result = ResultType.Successful;
                    Result.Message = "Data save change successful.";
                }
                catch (Exception exception)
                {
                    Exception ex = exception;
                    SQL_T.Rollback();
                    dbHelper.CloseConnection();
                    Result.Message = ex.Message;
                    Result.Result = ResultType.Failed;
                }
            }
            catch (Exception exception1)
            {
                Result.Message = exception1.Message;
                try
                {
                    dbHelper.CloseConnection();
                }
                catch
                {
                }
            }
            return Result;
        }

