        private const int MaxUploadedImageDimension = 1920;
        private const int MinimumImageSizeToOptimize = 1024 * 1024;

        private static string SaveUploadedFile(HttpPostedFile file, string destinationFolder)
        {
            string fileName = Path.GetFileName(file.FileName);
            string destinationPath = Path.Combine(destinationFolder, fileName);
            string extension = Path.GetExtension(fileName);
            bool isPng = string.Equals(extension, ".png", StringComparison.OrdinalIgnoreCase);
            bool isJpeg = string.Equals(extension, ".jpg", StringComparison.OrdinalIgnoreCase)
                || string.Equals(extension, ".jpeg", StringComparison.OrdinalIgnoreCase);

            file.SaveAs(destinationPath);
            if ((!isPng && !isJpeg) || file.ContentLength <= MinimumImageSizeToOptimize)
                return fileName;

            byte[] optimizedImage;
            bool preservePngTransparency = false;
            try
            {
                using (var image = Image.FromFile(destinationPath))
                {
                    NormalizeImageOrientation(image);

                    double scale = Math.Min(1d, (double)MaxUploadedImageDimension / Math.Max(image.Width, image.Height));
                    int width = Math.Max(1, (int)Math.Round(image.Width * scale));
                    int height = Math.Max(1, (int)Math.Round(image.Height * scale));
                    preservePngTransparency = isPng && image is Bitmap && HasTransparency((Bitmap)image);

                    using (var bitmap = new Bitmap(width, height, isPng ? PixelFormat.Format32bppArgb : PixelFormat.Format24bppRgb))
                    using (var graphics = Graphics.FromImage(bitmap))
                    using (var output = new MemoryStream())
                    {
                        graphics.Clear(isPng ? Color.Transparent : Color.White);
                        graphics.Clear(preservePngTransparency ? Color.Transparent : Color.White);
                        graphics.CompositingMode = System.Drawing.Drawing2D.CompositingMode.SourceOver;
                        graphics.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;
                        graphics.PixelOffsetMode = System.Drawing.Drawing2D.PixelOffsetMode.HighQuality;
                        graphics.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.HighQuality;
                        graphics.DrawImage(image, 0, 0, width, height);

                        preservePngTransparency = isPng && HasTransparency(bitmap);
                        if (preservePngTransparency)
                        {
                            bitmap.Save(output, ImageFormat.Png);
                        }
                        else
                        {
                            ImageCodecInfo jpegEncoder = ImageCodecInfo.GetImageEncoders()
                                .FirstOrDefault(codec => codec.FormatID == ImageFormat.Jpeg.Guid);
                            if (jpegEncoder == null)
                                return fileName;

                            using (var encoderParameters = new EncoderParameters(1))
                            {
                                encoderParameters.Param[0] = new EncoderParameter(System.Drawing.Imaging.Encoder.Quality, 82L);
                                bitmap.Save(output, jpegEncoder, encoderParameters);
                            }
                        }

                        optimizedImage = output.ToArray();
                    }
                }
            }
            catch (ArgumentException)
            {
                return fileName;
            }
            catch (System.Runtime.InteropServices.ExternalException)
            {
                return fileName;
            }

            if (optimizedImage.Length >= file.ContentLength)
                return fileName;

            string storedFileName = isPng && !preservePngTransparency
          ? Path.GetFileNameWithoutExtension(fileName) + "-compressed-" + Guid.NewGuid().ToString("N").Substring(0, 8) + ".jpg"
          : fileName;
            string optimizedPath = Path.Combine(destinationFolder, storedFileName);
            File.WriteAllBytes(optimizedPath, optimizedImage);

            if (!string.Equals(destinationPath, optimizedPath, StringComparison.OrdinalIgnoreCase))
                File.Delete(destinationPath);

            return storedFileName;
        }

        private static void NormalizeImageOrientation(Image image)
        {
            const int orientationPropertyId = 0x0112;
            try
            {
                var orientation = image.GetPropertyItem(orientationPropertyId).Value[0];
                switch (orientation)
                {
                    case 2: image.RotateFlip(RotateFlipType.RotateNoneFlipX); break;
                    case 3: image.RotateFlip(RotateFlipType.Rotate180FlipNone); break;
                    case 4: image.RotateFlip(RotateFlipType.Rotate180FlipX); break;
                    case 5: image.RotateFlip(RotateFlipType.Rotate90FlipX); break;
                    case 6: image.RotateFlip(RotateFlipType.Rotate90FlipNone); break;
                    case 7: image.RotateFlip(RotateFlipType.Rotate270FlipX); break;
                    case 8: image.RotateFlip(RotateFlipType.Rotate270FlipNone); break;
                }

                image.RemovePropertyItem(orientationPropertyId);
            }
            catch (ArgumentException)
            {
            }
        }

        private static bool HasTransparency(Bitmap bitmap)
        {
            if ((bitmap.PixelFormat & PixelFormat.Indexed) != 0)
                return true;

            var bounds = new Rectangle(0, 0, bitmap.Width, bitmap.Height);
            var bitmapData = bitmap.LockBits(bounds, ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
            try
            {
                int rowLength = Math.Abs(bitmapData.Stride);
                var row = new byte[rowLength];
                for (int y = 0; y < bitmapData.Height; y++)
                {
                    IntPtr rowPointer = IntPtr.Add(bitmapData.Scan0, y * bitmapData.Stride);
                    System.Runtime.InteropServices.Marshal.Copy(rowPointer, row, 0, rowLength);
                    for (int x = 3; x < rowLength; x += 4)
                    {
                        if (row[x] < 255)
                            return true;
                    }
                }
                return false;
            }
            finally
            {
                bitmap.UnlockBits(bitmapData);
            }
        }

