        public string XMLDataObj(Dictionary<string, object> ObjData)
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine("<Data>");
            foreach (dynamic Name in ObjData)
            {
                foreach (dynamic lData in Name.Value)
                {
                    sb.AppendLine("<" + Name.Key + ">");
                    foreach (dynamic item in lData)
                    {
                        if (item.Value != null)
                        {
                            string key = item.Key;
                            string value = HttpUtility.UrlDecode(item.Value.ToString().Trim());
                            sb.AppendLine("<" + key + ">" + EscapeXml(value) + "</" + key + ">");
                        }
                    }
                    sb.AppendLine("</" + Name.Key + ">");
                }
            }
            sb.AppendLine("</Data>");
            return sb.ToString();
        }
        public SqlResult SaveChangeDataTableNameWithObjData(Dictionary<string, object> TableNameWithObjData, Dictionary<string, object> DelTblWithPrimaryField)
        {
            SqlResult Result = new SqlResult();
            DBHelper dbHelper = new DBHelper();
            dbHelper.InitiateConnection();
            SqlTransaction SQL_T = dbHelper.sqlConnection.BeginTransaction();
            SqlCommand SQL_C = dbHelper.sqlConnection.CreateCommand();
            SQL_C.Transaction = SQL_T;
            try
            {
                string SQL = "";
                SQL_C.CommandType = CommandType.Text;
                string FieldName = "", Value = "";
                StringBuilder sbFieldName = new StringBuilder();
                StringBuilder sbValue = new StringBuilder();
                foreach (dynamic item in DelTblWithPrimaryField)
                {
                    foreach (var fieldInfo in item.Value.GetType().GetProperties())
                    {
                        var Key = fieldInfo.Name;
                        var Value_ = fieldInfo.GetMethod.Invoke(item.Value, null).ToString();
                        SQL = "delete from dbo." + item.Key + " where " + Key + " = @" + Key;
                        SQL_C.Parameters.AddWithValue("@" + Key, Value_);
                        SQL_C.CommandText = SQL;
                        SQL_C.ExecuteNonQuery();
                        SQL_C.Parameters.Clear();
                    }
                }

                foreach (dynamic Name in TableNameWithObjData)
                {
                    if (Name.Value != null)
                    {
                        foreach (dynamic list in Name.Value)
                        {
                            sbFieldName.Append("insert into dbo." + Name.Key + "(");
                            sbValue.Append(" Values (");
                            FieldName = "";
                            Value = "";
                            foreach (dynamic item in list)
                            {
                                string value_ = HttpUtility.UrlDecode(item.Value.ToString().Trim());
                                value_ = EscapeXml(value_);

                                if (FieldName == "")
                                    FieldName = item.Key;
                                else
                                    FieldName += "," + item.Key;

                                if (Value == "")
                                    Value = "@" + item.Key;
                                else
                                    Value += "," + "@" + item.Key;
                                SQL_C.Parameters.AddWithValue("@" + item.Key, value_.ToString().Trim());
                                //if (Value == "")
                                //    Value = value_;
                                //else
                                //    Value += "," + value_;

                                //string key = item.Key;
                                //string value = HttpUtility.UrlDecode(item.Value.ToString().Trim());
                                //sbValue.AppendLine("<" + key + ">" + EscapeXml(value) + "</" + key + ">");
                            }
                            sbFieldName.Append(FieldName);
                            sbFieldName.Append(")");
                            sbValue.Append(Value);
                            sbValue.Append(");");
                            sbFieldName.Append(sbValue.ToString());
                            SQL = sbFieldName.ToString();
                            sbFieldName.Clear();
                            sbValue.Clear();
                            SQL_C.CommandText = SQL;
                            SQL_C.ExecuteNonQuery();
                            SQL_C.Parameters.Clear();
                        }

                    }
                }
                SQL_T.Commit();
                dbHelper.CloseConnection();
                Result.Result = ResultType.Successful;
                Result.Message = "Data save change successful.";
            }
            catch (Exception ex)
            {
                SQL_T.Rollback();
                dbHelper.CloseConnection();
                Result.Message = ex.Message;
                Result.Result = ResultType.Failed;
            }

            //foreach (dynamic Name in ListName)
            //{
            //    sb.AppendLine("<" + Name + ">");
            //    foreach (dynamic lData in ListData)
            //    {
            //        foreach (dynamic item in lData)
            //        {
            //            if (item.Value != null)
            //            {
            //                string key = item.Key;
            //                string value = HttpUtility.UrlDecode(item.Value.ToString().Trim());
            //                sb.AppendLine("<" + key + ">" + EscapeXml(value) + "</" + key + ">");
            //            }
            //        }
            //    }
            //    sb.AppendLine("</" + Name + ">");
            //}
            return Result;
        }
        public DataTable GetDataForEdit(string SQL)
        {
            DBHelper dbHelper = new DBHelper();
            Common common = new Common();
            DataTable DT = new DataTable();
            dbHelper.InitiateConnection();
            DT = common.ExecuteDataTable(new SqlCommand(SQL, dbHelper.sqlConnection));
            dbHelper.CloseConnection();
            return DT;
        }
        private bool IsTableExisting(string table)
        {
            DBHelper dbHelper = new DBHelper();
            dbHelper.InitiateConnection();
            string command = $"select TABLE_NAME from INFORMATION_SCHEMA.TABLES where table_name = '" + table + "'";
            using (SqlCommand com = new SqlCommand(command, dbHelper.sqlConnection))
            {
                SqlDataReader reader = com.ExecuteReader();
                while (reader.Read())
                {
                    dbHelper.CloseConnection();
                    return true;
                }
                reader.Close();
            }
            dbHelper.CloseConnection();
            return false;
        }
