            DBHelper dbHelper = new DBHelper();
            string[] fieldName;
            SqlResult Result = new SqlResult();
            string TblName = EncryAndDecry.Decryp(TableName);
            FieldName = EncryAndDecry.Decryp(FieldName);
            string UserName = "";
            int SystemID = 0;
            int WarehouseID = 0;
            var xCustomHeader = HttpContext.Current.Request.Headers["x-custom-header"] == null ? "" : HttpContext.Current.Request.Headers["x-custom-header"];
            if (xCustomHeader != "" && xCustomHeader != "{}")
            {
                dynamic obj = JsonConvert.DeserializeObject(xCustomHeader);
                int UserID = obj.UserID;
                UserName = obj.UserName;
                SystemID = obj.SystemID;
                WarehouseID = obj.WarehouseID;
                UserFullName = obj.UserFullName;
                DomainID = obj.DomainID;
            }
            dbHelper.InitiateConnection();
            SqlTransaction SQL_T = dbHelper.sqlConnection.BeginTransaction();
            SqlCommand SQL_C = dbHelper.sqlConnection.CreateCommand();
            SQL_C.CommandType = CommandType.Text;
            SQL_C.Transaction = SQL_T;
            try
            {
                string SQL = "";
                DeletePrimaryTblName = EncryAndDecry.Decryp(DeletePrimaryTblName);
                if (DeleteWithTableName != "")
                {
                    if (TblName != "")
                    {
                        SQL = "delete from " + TblName + " where " + FieldName + " = @" + FieldName;
                        SQL_C.CommandText = SQL;
                        SQL_C.CommandType = CommandType.Text;
                        SQL_C.Parameters.Add(new SqlParameter(FieldName, DataID));
                        SQL_C.ExecuteNonQuery();
                        SQL_C.Parameters.Clear();
                    }
                    DeletePrimaryFiledName = EncryAndDecry.Decryp(DeletePrimaryFiledName);
                    DeletePrimaryTblNameDependOnTblName = EncryAndDecry.Decryp(DeletePrimaryTblNameDependOnTblName);
                    if (DeletePrimaryTblName != "" && DeletePrimaryTblNameDependOnTblName != "")
                    {
                        SQL = "select count(" + DeletePrimaryFiledName + ") from " + DeletePrimaryTblNameDependOnTblName + " ";
                        SQL += "where " + DeletePrimaryFiledName + " = @" + DeletePrimaryFiledName;
                        SQL_C.CommandText = SQL;
                        SQL_C.CommandType = CommandType.Text;
                        SQL_C.Parameters.Add(new SqlParameter(DeletePrimaryFiledName, DeletePrimaryValue));
                        DataSet ds = ExecuteDataSet(SQL_C);
                        SQL_C.Parameters.Clear();
                        if (int.Parse(ds.Tables[0].Rows[0][0].ToString()) == 1)
                        {
                            SQL = "delete from " + DeletePrimaryTblName + " where " + DeletePrimaryFiledName + " = @" + DeletePrimaryFiledName;
                            SQL_C.CommandText = SQL;
                            SQL_C.Parameters.Add(new SqlParameter(DeletePrimaryFiledName, DeletePrimaryValue));
                            SQL_C.ExecuteNonQuery();
                            SQL_C.Parameters.Clear();
                        }
                    }
                    else if (DeletePrimaryTblName != "")
                    {
                        SQL = "delete from " + DeletePrimaryTblName + " where " + DeletePrimaryFiledName + " = @" + DeletePrimaryFiledName;
                        SQL_C.CommandText = SQL;
                        SQL_C.Parameters.Add(new SqlParameter(DeletePrimaryFiledName, DataID));
                        SQL_C.ExecuteNonQuery();
                        SQL_C.Parameters.Clear();
                    }
                    string[] tbl = EncryAndDecry.Decryp(DeleteWithTableName).ToString().Split(new char[] { ',' });
                    foreach (string str in tbl)
                    {
                        if (str != "")
                        {
                            SQL = "delete from " + str + " where " + FieldName + " = @" + FieldName;
                            SQL_C.CommandText = SQL;
                            SQL_C.CommandType = CommandType.Text;
                            SQL_C.Parameters.Add(new SqlParameter(FieldName, DataID));
                            SQL_C.ExecuteNonQuery();
                            SQL_C.Parameters.Clear();
                        }
                    }
                }
                else if (DeleteUseProcedureName == "")
                {
                    TblName = EncryAndDecry.Decryp(TableName);
                    if (IsTableExisting(TblName + "_Log"))
                    {
                        // Parameterized SQL for log insert
                        SQL = "INSERT INTO " + TblName + "_Log " +
                              "SELECT *, 'Delete data from " + TblName + " by user: " + UserName + "' AS [Description], @CurrentDate AS [Date] " +
                              "FROM " + TblName + " WHERE " + FieldName + " = @DataID";

                        SQL_C.CommandText = SQL;
                        SQL_C.Parameters.Clear();
                        SQL_C.Parameters.Add(new SqlParameter("@DataID", DataID));
                        SQL_C.Parameters.Add(new SqlParameter("@CurrentDate", GetCurrentDate()));
                        SQL_C.ExecuteNonQuery();
                    }

                    // Delete statement
                    fieldName = new string[] { "DELETE FROM ", TblName, " WHERE ", FieldName, " = @", FieldName };
                    SQL_C.CommandText = string.Concat(fieldName);
                    SQL_C.Parameters.Clear();
                    SQL_C.Parameters.Add(new SqlParameter("@" + FieldName, DataID));
                    SQL_C.ExecuteNonQuery();
                }
                else
                {
                    SQL = EncryAndDecry.Decryp(DeleteUseProcedureName);
                    SQL_C.CommandType = CommandType.StoredProcedure;
                    SQL_C.CommandText = SQL;
                    FieldName = string.Concat("@", FieldName);
                    SQL_C.Parameters.Clear();
                    SqlCommand cm = new SqlCommand();
                    cm = new SqlCommand(SQL, dbHelper.sqlConnection)
                    {
                        Transaction = SQL_T,
                        CommandType = CommandType.StoredProcedure
                    };
                    SQL_C.CommandType = CommandType.StoredProcedure;
                    cm.CommandType = CommandType.StoredProcedure;

                    SqlCommandBuilder.DeriveParameters(cm);
                    foreach (SqlParameter p in cm.Parameters)
                    {
                        if (p.ParameterName == "@SystemID")
                            SQL_C.Parameters.AddWithValue("@SystemID", SystemID.ToString());
                        if (p.ParameterName == "@WarehouseID")
                            SQL_C.Parameters.AddWithValue("@WarehouseID", WarehouseID.ToString());
                        if (p.ParameterName == "@DomainID")
                            SQL_C.Parameters.AddWithValue("@DomainID", DomainID.ToString());
                        if (p.ParameterName == "@UserName")
                            SQL_C.Parameters.AddWithValue("@UserName", UserFullName);
                    }
                    SQL_C.Parameters.Add(new SqlParameter(FieldName, DataID));
                    SQL_C.ExecuteNonQuery();
                }
                SQL_T.Commit();
                dbHelper.CloseConnection();
                Result.Result = ResultType.Successful;
                Result.Message = "Delete data successful.";
            }
            catch (Exception ex)
            {
                Result.Result = ResultType.Failed;
                SQL_T.Rollback();
                dbHelper.CloseConnection();
                Result.Message = ex.Message;
            }
            return Result;
        }
        public SqlResult Detele(string SQL, string FieldName, string Data)
        {
            DBHelper dbHelper = new DBHelper();
            dbHelper.InitiateConnection();
            SqlResult Result = new SqlResult();
            SqlTransaction SQL_T = dbHelper.sqlConnection.BeginTransaction();
            SqlCommand SQL_C = dbHelper.sqlConnection.CreateCommand();
            SQL_C.CommandType = CommandType.Text;
            SQL_C.Transaction = SQL_T;
            try
            {
                SQL_C.CommandText = SQL;
                SQL_C.Parameters.Add(new SqlParameter("@" + FieldName, Data));
                SQL_C.ExecuteNonQuery();
                SQL_T.Commit();
                dbHelper.CloseConnection();
                Result.Result = ResultType.Successful;
                Result.Message = "Delete data successful.";
            }
            catch (Exception ex)
            {
                Result.Result = ResultType.Failed;
                SQL_T.Rollback();
                dbHelper.CloseConnection();
                Result.Message = ex.Message;
            }
            return Result;
        }

        public string JsonData(
            string SQL,
            bool isProcedure = false,
            Dictionary<string, string> Para = null,
            bool ReturnXML = false,
            string dbConnection = "",
            bool IsGetDataFromAPI = false,
            string Token = "",
            Dictionary<string, string> ReplaceJsonKey = null)
        {
            if (IsGetDataFromAPI)
            {
                try
                {
                    ServicePointManager.Expect100Continue = true;
                    ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;

                    using (var client = new HttpClient())
                    {
                        client.DefaultRequestHeaders.Authorization =
                            new AuthenticationHeaderValue("Bearer", Token);

                        var parsedObjects = new List<JObject>();
                        var sqls = SQL.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);

                        foreach (var sql in sqls)
                        {
                            var response = client
                                .GetAsync(sql.Trim())
                                .GetAwaiter()
                                .GetResult();

                            response.EnsureSuccessStatusCode();

                            var json = response.Content
                                .ReadAsStringAsync()
                                .GetAwaiter()
                                .GetResult();

                            var objects = new JavaScriptSerializer()
                                .Deserialize<List<object>>(json);

                            if (objects == null)
                            {
                                continue;
                            }

                            foreach (var item in objects)
                            {
                                var parsedObject = JObject.FromObject(item);

                                if (ReplaceJsonKey != null)
                                {
                                    foreach (var replacement in ReplaceJsonKey)
                                    {
                                        var parent = parsedObject[replacement.Key]?.Parent;

                                        if (parent != null)
                                        {
                                            SetKey(
                                                parsedObject,
                                                parent,
                                                replacement.Value);
                                        }
                                    }
                                }

                                parsedObjects.Add(parsedObject);
                            }
                        }

                        return parsedObjects.ToJsonString();
                    }
                }
                catch (Exception ex)
                {
                    return ex.Message;
                }
            }

            if (string.IsNullOrEmpty(dbConnection))
            {
                dbConnection = GetConnectionString();
            }

            var dataSet = new DataSet();

            using (var conn = new SqlConnection(dbConnection))
            using (var command = conn.CreateCommand())
            {
                command.CommandText = SQL;
                command.CommandType = isProcedure
                    ? CommandType.StoredProcedure
                    : CommandType.Text;
                command.CommandTimeout = 300;

                AddParameters(command, Para);

                conn.Open();

                if (!ReturnXML)
                {
                    var dataTable = new DataTable();

                    using (var reader = command.ExecuteReader())
                    {
                        dataTable.Load(reader);
                    }

                    return JsonConvert.SerializeObject(dataTable);
                }

                using (var adapter = new SqlDataAdapter(command))
                {
                    adapter.Fill(dataSet);
                }
            }

            return JsonConvert.SerializeObject(dataSet);
        }

        public DataSet LoadData(
            string sql,
            bool isStoredProcedure = false,
            Dictionary<string, string> parameters = null,
            string dbConnectionString = "")
        {
            var dbHelper = new DBHelper();

            try
            {
                if (!string.IsNullOrEmpty(dbConnectionString))
                {
                    dbHelper.ConnectionString = dbConnectionString;
                }

                dbHelper.InitiateConnection();

                using (var command = dbHelper.sqlConnection.CreateCommand())
                {
                    command.CommandText = sql;
                    command.CommandType = isStoredProcedure
                        ? CommandType.StoredProcedure
                        : CommandType.Text;
                    command.CommandTimeout = 180;

                    AddParameters(command, parameters);

                    return ExecuteDataSet(command);
                }
            }
            finally
            {
                dbHelper.CloseConnection();
            }
        }

