            }
            finally
            {
                dbHelper.CloseConnection();
            }
        }

        private void AddParameters(
            SqlCommand command,
            Dictionary<string, string> parameters)
        {
            if (parameters == null || parameters.Count == 0)
            {
                return;
            }

            foreach (var parameter in parameters)
            {
                command.Parameters.Add(
                    new SqlParameter(
                        parameter.Key,
                        parameter.Value ?? (object)DBNull.Value));
            }
        }

        private void AddParameters(
            SqlCommand command,
            Dictionary<string, object> parameters)
        {
            if (parameters == null || parameters.Count == 0)
            {
                return;
            }

            foreach (var parameter in parameters)
            {
                command.Parameters.Add(
                    new SqlParameter(
                        parameter.Key,
                        parameter.Value ?? DBNull.Value));
            }
        }

        public DataSet ExecuteDataSet(SqlCommand command)
        {
            var dataSet = new DataSet();

            using (var adapter = new SqlDataAdapter(command))
            {
                adapter.Fill(dataSet);
            }

            return dataSet;
        }


        public string JsonConvertDataTable(DataTable dt)
        {
            DataTable dts = UrlEncodeDataTable(dt);

            return JsonConvert.SerializeObject(dts);
        }
        public DataTable UrlEncodeDataTable(DataTable dt)
        {
            if (dt != null)
            {
                foreach (DataRow row in dt.Rows)
                {
                    foreach (DataColumn column in dt.Columns)
                    {
                        if (row[column] is string)
                        {
                            row[column] = WebUtility.HtmlEncode(row[column].ToString());
                        }
                    }
                }
            }
            return dt;
        }
        public DataSet UrlEncodeDataSet(DataSet ds)
        {
            foreach (DataTable table in ds.Tables)
            {
                foreach (DataRow row in table.Rows)
                {
                    foreach (DataColumn column in table.Columns)
                    {
                        if (row[column] is string)
                        {
                            row[column] = WebUtility.HtmlEncode(row[column].ToString());
                        }
                    }
                }
            }
            return ds;
        }
        public void SetKey(JObject parent, JToken token, string newKey)
        {
            var tokenProp = token as JProperty;
            var oldKeyName = tokenProp.Name;
            parent[newKey] = tokenProp.Value;
            parent.Remove(oldKeyName);
        }

        public string CheckExsitingDataField(string OldValue, string ConditionFiledName, string ConditonText, string CheckExsitingWithField, string FormID, string ISUniqueFiledWithSystemID = "", string CheckExsitingWithControllName = "", string TblName = "", int SystemID = 0, int WarehouseID = 0, string DomainID = "")
        {
            bool IS_UniqueFiledWithSystemID = bool.Parse(ISUniqueFiledWithSystemID);
            DBHelper dbHelper = new DBHelper();
            Exception ex;
            string Value = HttpUtility.UrlDecode(ConditonText).ToString().Trim();
            string IsExsitsingData = "TRUE";
            string FieldName = EncryAndDecry.Decryp(ConditionFiledName);
            TblName = EncryAndDecry.Decryp(TblName);
            if (DomainID == "") DomainID = this.DomainID;
            string[] strArrays = new string[] { "Select ", FieldName, " From [", TblName, "] Where SystemID = " + SystemID + " and WarehouseID= " + WarehouseID + " and DomainID like '%" + DomainID + "%' and LOWER(", FieldName, ") = @ConditonText" };
            if (!IS_UniqueFiledWithSystemID)
                strArrays = new string[] { "Select ", FieldName, " From [", TblName, "] Where LOWER(", FieldName, ") = @ConditonText" };
            string SQL = string.Concat(strArrays);
            if (CheckExsitingWithField != "" && CheckExsitingWithControllName != "")
            {
                string[] fields = CheckExsitingWithField.Split(',');
                string[] fieldvalus = CheckExsitingWithControllName.Split(',');
                int j = 0;
                foreach (string field in fields)
                {
                    SQL += " AND " + field + " = N'" + fieldvalus[j].ToString() + "'";
                    j++;
                }
            }
            else if (CheckExsitingWithField != "")
                SQL = string.Concat(SQL, " AND ", CheckExsitingWithField);
            if (OldValue != "")
            {
                Value = HttpUtility.UrlDecode(OldValue).ToString().Trim();
                if (OldValue != ConditonText)
                {
                    Value = HttpUtility.UrlDecode(ConditonText).ToString().Trim();
                    strArrays = new string[] { "Select ", FieldName, " From [", TblName, "] Where SystemID = " + SystemID + " and WarehouseID= " + WarehouseID + " and DomainID like '%" + DomainID + "%' and LOWER(", FieldName, ") = @ConditonText" };
                    if (!IS_UniqueFiledWithSystemID)
                        strArrays = new string[] { "Select ", FieldName, " From [", TblName, "] Where LOWER(", FieldName, ") = @ConditonText" };
                    SQL = string.Concat(strArrays);
                }
                else
                {
                    strArrays = new string[] { "Select ", FieldName, " From [", TblName, "] Where SystemID = " + SystemID + " and WarehouseID= " + WarehouseID + " and DomainID like '%" + DomainID + "%' and LOWER(", FieldName, ") <> @ConditonText" };
                    if (!IS_UniqueFiledWithSystemID)
                        strArrays = new string[] { "Select ", FieldName, " From [", TblName, "] Where LOWER(", FieldName, ") <> @ConditonText" };
                    SQL = string.Concat(strArrays);
                }

                if (CheckExsitingWithField != "" && CheckExsitingWithControllName != "")
                    SQL += " AND " + CheckExsitingWithField + " = N'" + CheckExsitingWithControllName + "'";
            }
            string Result;
            try
            {
                dbHelper.InitiateConnection();
                try
                {
                    SqlCommand SQL_C = new SqlCommand(SQL, dbHelper.sqlConnection);
                    SQL_C.Parameters.Add(new SqlParameter("ConditonText", Value.ToLower()));
                    //SQL_C.Parameters["@ConditonText"].Value = "N'" + Value.ToLower() + "'";
                    SqlDataReader SQL_D = SQL_C.ExecuteReader();
                    if (OldValue != "")
                    {
                        while (SQL_D.Read())
                        {
                            if (SQL_D[FieldName].ToString().ToLower() == HttpUtility.UrlDecode(ConditonText).ToLower().Trim())
                            {
                                IsExsitsingData = "FALSE";
                                break;
                            }
                            else
                            {
                                IsExsitsingData = "TRUE";
                                break;
                            }
                        }
                    }
                    else
                    {
                        IsExsitsingData = !SQL_D.Read() ? "TRUE" : "FALSE";
                    }
                    Result = IsExsitsingData;
                    SQL_D.Close();
                    dbHelper.CloseConnection();
                }
                catch (Exception exception)
                {
                    ex = exception;
                    dbHelper.CloseConnection();
                    Result = ex.Message;
                }
            }
            catch (Exception exception1)
            {
                ex = exception1;
                try
                {
                    dbHelper.CloseConnection();
                }
                catch
                {
                }
                Result = ex.Message;
            }
            return Result;
        }
        public Collection<AutoCompleteDTO> Autocomplete(string term, string SQL, bool IsUseConnection2 = false, string SQL2 = "", string ValueControlNameID = "", string ConditionField = "", string CboValue = "", string DisplayOnFields = "", string HiddenFeild = "")
        {
            Common common = new Common();
            DBHelper dbHelper = new DBHelper();
            SqlCommand SQL_C;
            string sQL;
            if (SQL != "")
            {
                CboValue = CboValue == "All" ? "" : CboValue;
                SQL = EncryAndDecry.Decryp(SQL);
                SQL = ReplaceFullWords(SQL, "@SearchText", "N'%' + @SearchText + '%'");
                SQL = ReplaceFullWords(SQL, "@SearchText2", CboValue);
            }
            if (ValueControlNameID != "")
            {
                if (ConditionField != "")
                {
                    sQL = SQL;
                    string[] conditionField = new string[] { sQL, " AND ", ConditionField, " = ", ValueControlNameID };
                    SQL = string.Concat(conditionField);
                }
            }
            Collection<AutoCompleteDTO> collection = new Collection<AutoCompleteDTO>();
            string Result;
            try
            {
                try
                {
                    DataTable dt = new DataTable();
                    if (IsUseConnection2 && SQL2 != "")
                    {
                        dbHelper.InitiateConnection2();
                        SQL2 = EncryAndDecry.Decryp(SQL2);
                        SQL2 = SQL2.Replace("@SearchText", "N'%' + @SearchText + '%'");
                        SqlCommand sqlCommand = new SqlCommand(SQL2, dbHelper.sqlConnection)
                        {
                            CommandType = CommandType.Text
                        };
                        SQL_C = sqlCommand;
                        SQL_C.Parameters.Clear();
                        SQL_C.Parameters.AddWithValue("@SearchText", term.ToLower());
                        dt = common.ExecuteDataTable(SQL_C);
                    }
                    if (dt.Rows.Count == 0)
                    {
                        dbHelper.InitiateConnection();
                        SqlCommand sqlCommand1 = new SqlCommand(SQL, dbHelper.sqlConnection)
                        {
                            CommandType = CommandType.Text
                        };
                        SQL_C = sqlCommand1;
                        SQL_C.Parameters.AddWithValue("@SearchText", term.ToLower());
                        if (ValueControlNameID != "" && ConditionField == "")
                        {
                            SQL_C.Parameters.AddWithValue("@Value", ValueControlNameID.ToLower());
                        }
                        dt = common.ExecuteDataTable(SQL_C);
                    }
                    JObject fields = new JObject();
                    JObject hiddenfields = new JObject();
                    foreach (DataRow dr in dt.Rows)
                    {
                        AutoCompleteDTO dto = new AutoCompleteDTO();
                        if (dt.Columns.Count > 1)
                        {
                            dto.id = dr[0].ToString();
                            string str1 = dr[1].ToString();
                            sQL = str1;
                            dto.label = str1;
                            dto.@value = sQL;
                            if (dt.Columns.Contains("Image"))
                            {
                                dto.image = dr["Image"].ToString();
                            }
                            if (DisplayOnFields != "")
                            {
                                string[] DisplayOnField = DisplayOnFields.Split(',');
                                foreach (string str in DisplayOnField)
                                {
                                    if (dt.Columns.Contains(str.Trim()))
                                    {
                                        fields[str.Trim()] = common.HtmlDecode(dr[str.Trim()].ToString());
                                    }
                                }
                                string[] DisplayOnHiddenField = HiddenFeild.Split(',');
                                foreach (string str in DisplayOnHiddenField)
                                {
                                    if (dt.Columns.Contains(str.Trim()))
                                    {
                                        hiddenfields[str.Trim()] = common.HtmlDecode(dr[str.Trim()].ToString());
                                    }
                                }
                            }
                        }
                        else
                        {
                            string str = common.HtmlDecode(dr[0].ToString());
                            sQL = str;
                            dto.label = str;
                            dto.@value = sQL;
                        }
                        dto.fields = JsonConvert.SerializeObject(fields);
                        dto.HiddenFeild = JsonConvert.SerializeObject(hiddenfields);
                        collection.Add(dto);
                    }
                    dbHelper.CloseConnection();
                }
                catch (Exception exception)
                {
                    Result = exception.Message;
                    dbHelper.CloseConnection();
                }
            }
            catch (Exception exception1)
            {
                Result = exception1.Message;
                try
                {
                    dbHelper.CloseConnection();
                }
                catch
                {
                }
            }
            return collection;
        }
        private string ReplaceFullWords(string s, string oldWord, string newWord)
        {
            string str;
            bool flag;
            if (s == null)
            {
                str = null;
            }
            else
            {
                int startIndex = 0;
                while (true)
                {
                    int position = s.IndexOf(oldWord, startIndex);
                    if (position == -1)
                    {
                        break;
                    }
                    int indexAfter = position + oldWord.Length;
                    flag = position != 0 && (IsWordChar(s[position - 1]) || (indexAfter != s.Length && IsWordChar(s[indexAfter])));
                    if (!flag)
                    {
                        s = string.Concat(s.Substring(0, position), newWord, s.Substring(indexAfter));
                        startIndex = position + newWord.Length;
                    }
                    else
                    {
                        startIndex = position + oldWord.Length;
                    }
                }
                str = s;
            }
            return str;
        }
        private bool IsWordChar(char c)
        {
            return char.IsLetterOrDigit(c) || c == '\u005F';
        }

        public bool HasPermission(string _permission)
        {
            return HttpContext.Current.User.IsInRole(_permission);
        }

        public string EscapeXml(string s)
        {
            string toxml = s;
            if (!string.IsNullOrEmpty(toxml))
            {
                // replace literal values with entities
                toxml = toxml.Replace("&", "&amp;");
                toxml = toxml.Replace("'", "&apos;");
                toxml = toxml.Replace("'", "&#39;");
                toxml = toxml.Replace("\"", "&quot;");
                toxml = toxml.Replace(">", "&gt;");
                toxml = toxml.Replace("<", "&lt;");
            }
            if (toxml == null || toxml == "null")
                toxml = "";
            return toxml;
        }
        public string UnescapeXml(string s)
        {
            string unxml = s;
            if (!string.IsNullOrEmpty(unxml))
            {
                // replace entities with literal values
                unxml = unxml.Replace("&apos;", "'");
                unxml = unxml.Replace("&quot;", "\"");
                unxml = unxml.Replace("&gt;", ">");
                unxml = unxml.Replace("&lt;", "<");
                unxml = unxml.Replace("&amp;", "&");
            }
            return unxml;
        }
        public string ConvertStringToDate(string strDate)
        {
            DateTime timeNow = DateTime.Now;
            TimeZoneInfo easternZone = TimeZoneInfo.FindSystemTimeZoneById("SE Asia Standard Time");
            DateTime easternTimeNow = TimeZoneInfo.ConvertTime(timeNow, TimeZoneInfo.Local, easternZone);
            DateTime date = DateTime.ParseExact(strDate, "dd/MM/yyyy", CultureInfo.InvariantCulture);
            return date.ToString("yyyy/MM/dd") + " " + easternTimeNow.ToString("HH:mm:ss");
        }

        public string StringToDate(string DateData)
        {
            DateTime date = DateTime.Parse(DateData);//, "dd/MM/yyyy", null
            DateTime timeNow = DateTime.Now;
            TimeZoneInfo easternZone = TimeZoneInfo.FindSystemTimeZoneById("SE Asia Standard Time");
            DateTime easternTimeNow = TimeZoneInfo.ConvertTime(timeNow, TimeZoneInfo.Local, easternZone);
            return date.ToString("yyyy/MM/dd") + " " + easternTimeNow.ToString("HH:mm:ss");
        }

