        public SqlResult DeleteAttachmentFile(string DestinationFile, string DeleteFileName, dynamic KeepFileName, string SQL, Dictionary<string, string> Para = null)
        {
            string FilePath = HttpContext.Current.Server.MapPath(@"" + DestinationFile);
            if (System.IO.File.Exists(FilePath + DeleteFileName))
            {
                System.IO.File.Delete(FilePath + DeleteFileName);
            }

            DBHelper dbHelper = new DBHelper();
            SqlResult Result = new SqlResult();
            dbHelper.InitiateConnection();
            SqlTransaction SQL_T = dbHelper.sqlConnection.BeginTransaction();
            SqlCommand SQL_C = dbHelper.sqlConnection.CreateCommand();
            SQL_C.CommandType = CommandType.Text;
            try
            {
                if (Para != null && Para.Count > 0)
                {
                    SQL_C.CommandText = SQL;
                    foreach (KeyValuePair<string, string> item in Para)
                    {
                        SQL_C.Parameters.Add(new SqlParameter(item.Key, item.Value));
                    }
                }
                else
                {
                    SQL_C.CommandText = SQL;
                }
                SQL_C.Transaction = SQL_T;
                SQL_C.ExecuteNonQuery();
                SQL_T.Commit();
                dbHelper.CloseConnection();
                Result.Result = ResultType.Successful;
                Result.Message = "Data save change successful.";
            }
            catch (Exception exception)
            {
                Exception ex = exception;
                SQL_T.Rollback();
                dbHelper.CloseConnection();
                Result.Message = ex.Message;
                Result.Result = ResultType.Failed;
            }
            return Result;
        }
        public string FixBase64ForImage(string Image)
        {
            StringBuilder sbText = new StringBuilder(Image, Image.Length);
            sbText.Replace("\r\n", string.Empty); sbText.Replace(" ", string.Empty);
            return sbText.ToString();
        }
        public string UploadToServer(byte[] image, string Destination, string fileName, bool isPDF = false, bool UnixEpochMethod = true)
        {
            HTML html = new HTML();
            var localPath = HttpContext.Current.Request.Url.GetLeftPart(UriPartial.Authority);
            var root = HttpContext.Current.Server.MapPath(@"/" + Destination + "/" + fileName + "/");
            fileName = $"{html.ToUrlSlug($"{fileName}")}";
            string filePath;
            try
            {
                if (!isPDF)
                {
                    if (!Directory.Exists(root))
                        Directory.CreateDirectory(root);
                    var bm = ByteArrayToImage(image);
                    //filePath = $"{ToUrlSlug($"IMG-{GetUnixEpochMethod(DateTime.Now)}-{fileName}")}.{ImageFormat.Jpeg}";
                    filePath = UnixEpochMethod
                        ? fileName + $"{html.ToUrlSlug($"-{html.GetUnixEpochMethod(DateTime.Now)}")}.{ImageFormat.Jpeg}"
                        : fileName + $".{ImageFormat.Jpeg}";
                    var filePathUpdated = System.IO.Path.Combine(root, filePath);
                    bm.Save(filePathUpdated, ImageFormat.Jpeg);
                    bm.Dispose();
                }
                else
                {
                    if (UnixEpochMethod)
                    {
                        if (!Directory.Exists(root))
                            Directory.CreateDirectory(root);
                        filePath = $"{html.ToUrlSlug($"{fileName}-{html.GetUnixEpochMethod(DateTime.Now)}")}.pdf";
                    }
                    else
                    {
                        root = HttpContext.Current.Server.MapPath(@"/" + Destination);
                        if (!Directory.Exists(root))
                            Directory.CreateDirectory(root);
                        filePath = fileName + ".pdf";
                    }
                    var filePathUpdated = System.IO.Path.Combine(root, filePath);
                    //System.IO.File(filePathUpdated, "application/pdf");
                    System.IO.File.WriteAllBytes(filePathUpdated, image);
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
            //return localPath + "/Uploads/" + filePathroot + ;
            return filePath;
        }
        protected Image ByteArrayToImage(byte[] byteArrayIn)
        {
            var converter = new ImageConverter();
            var img = (Image)converter.ConvertFrom(byteArrayIn);
            return img;
        }

        public SqlResult SendEmailToCustomer(string Subject, string CustomerName, string EmailAddress, string MessageBody)
        {
            SqlResult sqlResult = new SqlResult();
            try
            {
                MailMessage message = new MailMessage();
                SmtpClient smtp = new SmtpClient();
                EmailProperty emailProperty = new EmailProperty();
                smtp.Port = emailProperty.Port;
                smtp.Host = emailProperty.Host;
                smtp.EnableSsl = true;
                smtp.UseDefaultCredentials = false;
                smtp.Credentials = new NetworkCredential(emailProperty.CredentialsEmail, emailProperty.CredentialsPassword);
                smtp.DeliveryMethod = SmtpDeliveryMethod.Network;
                message.From = new MailAddress(emailProperty.EmailFrom, "NSM SOLUTION CO.,LTD");
                message.Subject = Subject;
                message.SubjectEncoding = Encoding.UTF8;
                message.IsBodyHtml = true;
                string FilePath = HttpContext.Current.Server.MapPath("~/Templates/EmailTemplate.html");
                StreamReader str = new StreamReader(FilePath);
                string MailText = str.ReadToEnd();
                str.Close();
                MailText = MailText.Replace("{Title}", Subject);
                MailText = MailText.Replace("{CustomerName}", CustomerName);
                MailText = MailText.Replace("{MessageBody}", MessageBody);
                message.Body = MailText.ToString();
                message.BodyEncoding = Encoding.UTF8;
                smtp.Send(message);
                sqlResult.Result = ResultType.Successful;
                sqlResult.Message = "Sent successful.";
            }
            catch (Exception ex)
            {
                sqlResult.Result = ResultType.Failed;
                sqlResult.Message = ex.Message;
            }
            return sqlResult;
        }

