        public string GetLocalIPAddress(out string hostname)
        {
            var host = Dns.GetHostEntry(Dns.GetHostName());
            foreach (var ip in host.AddressList)
            {
                if (ip.AddressFamily == AddressFamily.InterNetwork)
                {
                    hostname = host.HostName;
                    return ip.ToString();
                }
            }
            throw new Exception("No network adapters with an IPv4 address in the system!");
        }

        public async Task<SqlResult> GenerateInvoice(int GenerateBeforeDay = 7, string GenerateDate = "", string GenerateBy = "System", int System_ID = 13, int Warehouse_ID = 16, bool UploadToServer = false, string Domain_ID = "001")
        {
            SqlResult sqlResult = new SqlResult();
            try
            {
                DateTime timeNow = DateTime.Now;
                TimeZoneInfo easternZone = TimeZoneInfo.FindSystemTimeZoneById("SE Asia Standard Time");
                DateTime easternTimeNow = TimeZoneInfo.ConvertTime(timeNow, TimeZoneInfo.Local, easternZone);
                HTML html = new HTML();
                if (GenerateDate == "")
                    GenerateDate = easternTimeNow.ToString();
                string sql = "SP_GENERATE_INVOICE";
                Dictionary<string, string> para = new Dictionary<string, string>
                {
                    { "GenerateInvoiceDate", GenerateDate },
                    { "GenerateBeforeDay", GenerateBeforeDay.ToString() },
                    { "GeneratedBy", GenerateBy },
                    { "SystemID", System_ID.ToString() },
                    { "WarehouseID", Warehouse_ID.ToString() },
                    { "DomainID", Domain_ID.ToString() }
                };
                sqlResult = html.SaveChangeData(sql, true, para, true, true);
                StringBuilder sb = new StringBuilder();
                foreach (DataRow dr in sqlResult.Data.Tables[0].Rows)
                {
                    int CustomerID = int.Parse(dr["CustomerID"].ToString());
                    string InvoiceNo = dr["InvoiceNo"].ToString();
                    int IsIncludedVAT = int.Parse(dr["IsIncludedVAT"].ToString());
                    int SystemID = int.Parse(dr["SystemID"].ToString());
                    int WarehouseID = int.Parse(dr["WarehouseID"].ToString());
                    string DomainID = dr["DomainID"].ToString();
                    int StatusID = int.Parse(dr["StatusID"].ToString());
                    string CustomerName = dr["CustomerName"].ToString();
                    string CustomerCode = dr["CustomerCode"].ToString();
                    sqlResult = await InvoiceToPDFandUpload(CustomerName, CustomerCode, CustomerID, InvoiceNo, easternTimeNow.ToString(), IsIncludedVAT, StatusID, System_ID, Warehouse_ID, UploadToServer);
                    if (sqlResult.Result == ResultType.Successful)
                        sqlResult.Message = "Generate Invoice Successful.";
                }
            }
            catch (Exception ex)
            {
                sqlResult.Message = ex.Message;
                sqlResult.Result = ResultType.Failed;
            }
            return sqlResult;
        }
