        public async Task<SqlResult> InvoiceToPDFandUpload(string CustomerName, string CustomerCode, int CustomerID, string InvoiceNo, string InvoiceDate, int IsIncludedVAT, int StatusID, int SystemID, int WarehouseID, bool UploadToServer = false, string OfficialReceiptNo = "", string DestinationFolder = "/ISP_Invoice/", bool ISShowPeriod = true, string Type = "", string DomainID = "")
        {
            DateTime timeNow = DateTime.Now;
            TimeZoneInfo easternZone = TimeZoneInfo.FindSystemTimeZoneById("SE Asia Standard Time");
            DateTime easternTimeNow = TimeZoneInfo.ConvertTime(timeNow, TimeZoneInfo.Local, easternZone);
            HTML html = new HTML();
            SqlResult sqlResult = new SqlResult();
            string Customer_Name = $"{html.ToUrlSlug($"{CustomerName + " [" + CustomerCode + "]"}")}";
            CustomerName = $"{html.ToUrlSlug($"{CustomerName + " [" + CustomerCode + "]"}")}";
            string FilePath = HttpContext.Current.Server.MapPath(@"~/Uploads/CustomerAttFiles/" + CustomerName);
            string CustFilePart = HttpContext.Current.Server.MapPath(@"~/Uploads/CustomerAttFiles/" + CustomerName);
            if (!Directory.Exists(FilePath + "\\Invoices"))
                Directory.CreateDirectory(FilePath + "\\Invoices");
            if (!Directory.Exists(FilePath + "\\Receipts"))
                Directory.CreateDirectory(FilePath + "\\Receipts");
            string Invoice_No = $"{html.ToUrlSlug($"{InvoiceNo}")}";
            CustomerName = $"{html.ToUrlSlug($"{CustomerCode}")}";
            string InvDate = DateTime.Parse(InvoiceDate).ToString("yyyyMMdd");
            string pdfFileName = InvDate + "-" + CustomerName + "_" + Invoice_No + ".pdf";
            string outputFile = FilePath + "\\Invoices\\" + pdfFileName;

            Dictionary<string, string> Para = new Dictionary<string, string>()
                {
                    { "SystemID", SystemID.ToString() },
                    { "WarehouseID", WarehouseID.ToString() },
                    { "CustID", CustomerID.ToString() },
                    {"InvoiceNo", InvoiceNo },
                    { "ISVAT", IsIncludedVAT.ToString() },
                    { "ISShowPeriod", "1"},
                    { "Type", "" },
                    { "DomainID", DomainID }
                };
            DataSet ds3 = html.LoadData("SP_CUSTOMER_INVOICE", true, Para);
            string DrawInvoice = html.DrawInvoice(ds3, false, IsIncludedVAT, StatusID, false);
            string FilePaths = html.httpContext.Server.MapPath("~/Templates/HtmlTemplate.html");
            StreamReader str = new StreamReader(FilePaths);
            string Text = str.ReadToEnd();
            str.Close();

            Text = Text.Replace("{Title}", "Customer Invoice");
            Text = Text.Replace("{BodyMessage}", DrawInvoice);
            var content = Text;
            var fileTmpPath = html.httpContext.Server.MapPath("~/Uploads");
            if (!System.IO.Directory.Exists(fileTmpPath))
            {
                System.IO.Directory.CreateDirectory(fileTmpPath);
            }
            var fileTmpName = Guid.NewGuid() + ".html";
            fileTmpName = System.IO.Path.Combine(fileTmpPath, fileTmpName);
            StreamWriter sw1 = new StreamWriter(fileTmpName);
            sw1.Write(content);
            sw1.Flush();
            sw1.Close();
            sw1.Dispose();

            var browser = await GetBrowserAsync();
            var page = await browser.NewPageAsync();

            try
            {
                string imgFileName = InvDate + "-" + CustomerName + "_" + Invoice_No + ".png";
                string outputFileimg = FilePath + "\\Invoices\\" + imgFileName;

                if (html.SystemID == "")
                    html.SystemID = SystemID.ToString();
                if (html.WarehouseID == "")
                    html.WarehouseID = WarehouseID.ToString();

                //await page.GoToAsync(url);
                await page.GoToAsync(fileTmpName);
                await page.GetContentAsync();
                await page.EvaluateExpressionHandleAsync("document.fonts.ready");

                if (System.IO.File.Exists(outputFile))
                {
                    FileInfo file = new FileInfo(outputFile);
                    try
                    {
                        System.GC.Collect();
                        System.GC.WaitForPendingFinalizers();
                        file.Delete();
                    }
                    catch (IOException)
                    {
                        pdfFileName = InvDate + "-" + CustomerName + "_" + Invoice_No + "_" + Guid.NewGuid() + ".pdf";
                        outputFile = FilePath + "\\Invoices\\" + pdfFileName;
                    }
                }
                await page.PdfAsync(outputFile, new PdfOptions
                {
                    Format = PaperFormat.A4,
                    PrintBackground = true,
                    DisplayHeaderFooter = false,
                    MarginOptions = new MarginOptions
                    {
                        Top = "0mm",
                        Bottom = "0mm",
                        Left = "0mm",
                        Right = "5mm"
                    }
                });

                sqlResult.Result = ResultType.Successful;
                sqlResult.Message = "Invoice to PDF file successful.";
                sqlResult.OutPutFile = CustFilePart + "/Invoices/" + pdfFileName;
                //
                if (UploadToServer)
                {

                    SqlResult sqlResult2 = await UploadFileToServer(FilePath + "\\Invoices", pdfFileName, DestinationFolder);
                    if (sqlResult2.Result == ResultType.Successful)
                    {
                        string sql = "update dbo.TblCustomerBillingInvoice set IsUploaded = 1 where CustomerID = " + CustomerID + " InvoiceNo ='" + InvoiceNo + "' and SystemID = " + html.SystemID + " and WarehouseID = " + html.WarehouseID;
                        sql += ";update dbo.TblCustomerBillInformation set IsUploaded = 1 where CustomerID = " + CustomerID + " InvoiceNo ='" + InvoiceNo + "' and SystemID = " + html.SystemID + " and WarehouseID = " + html.WarehouseID;
                        sql += ";update dbo.TblCustomerBalance set IsUploadToFTP = 1, UploadMessage=N'" + sqlResult.Message + "', UploadDate='" + GetCurrentDate() + "' where InvoiceNo = '" + InvoiceNo + "' and CustomerID = " + CustomerID;
                        html.SaveChangeData(sql, false, false);
                    }
                }

            }
            catch (Exception ex)
            {
                sqlResult.Message = "Invoice to PDF file failed. " + ex.Message;
                sqlResult.Result = ResultType.Failed;
            }

            await page.CloseAsync();

            if (System.IO.File.Exists(fileTmpName))
            {
                System.GC.Collect();
                System.GC.WaitForPendingFinalizers();
                FileInfo file = new FileInfo(fileTmpName);
                file.Delete();
            }
            return sqlResult;
        }
