        protected virtual bool IsFileLocked(FileInfo file)
        {
            FileStream stream = null;

            try
            {
                stream = file.Open(FileMode.Open, FileAccess.ReadWrite, FileShare.None);
            }
            catch (IOException)
            {
                //the file is unavailable because it is:
                //still being written to
                //or being processed by another thread
                //or does not exist (has already been processed)
                return true;
            }
            finally
            {
                if (stream != null)
                    stream.Close();
            }

            //file is not locked
            return false;
        }
        public async Task<SqlResult> URLtoPDF(string URL, string URLParamenter = "", string DestinationFolder = "", string FileName = "")
        {
            Dictionary<string, string> rateDict = new JavaScriptSerializer().Deserialize<Dictionary<string, string>>(URLParamenter);
            string para = "";
            if (rateDict != null)
            {
                foreach (KeyValuePair<string, string> pair in rateDict)
                {
                    if (para == "")
                        para = "{" + "\"" + pair.Key + "\"" + ":" + "\"" + pair.Value + "\"";
                    else
                        para += ",\"" + pair.Key + "\"" + ":" + "\"" + pair.Value + "\"";
                }
                para += "}";
                para = "PrimaryFieldValue=" + para;
            }
            DateTime timeNow = DateTime.Now;
            TimeZoneInfo easternZone = TimeZoneInfo.FindSystemTimeZoneById("SE Asia Standard Time");
            DateTime easternTimeNow = TimeZoneInfo.ConvertTime(timeNow, TimeZoneInfo.Local, easternZone);
            HTML html = new HTML();
            SqlResult sqlResult = new SqlResult();
            string uri = HttpContext.Current.Request.Url.GetLeftPart(UriPartial.Authority) + "/";
            IPage page = null;
            try
            {
                URL = para != "" ? uri + URL + "?" + para : uri + URL;

                FileName = $"{html.ToUrlSlug($"{FileName}")}";
                string FilePath = HttpContext.Current.Server.MapPath(@"/" + DestinationFolder + "/" + FileName);
                string outputUrlFile = "/" + DestinationFolder + "/" + FileName + "/";
                string outputUrlImg = "/" + DestinationFolder + "/" + FileName + "/";
                if (!Directory.Exists(FilePath))
                    Directory.CreateDirectory(FilePath);
                string Date = DateTime.Parse(GetCurrentDate()).ToString("yyyyMMdd");
                string pdfFileName = Date + "-" + FileName + ".pdf";
                string outputFile = System.IO.Path.Combine(FilePath, pdfFileName);
                outputUrlFile += pdfFileName;

                string imgFileName = Date + "-" + FileName + ".png";
                string outputFileimg = FilePath + "\\" + imgFileName;
                outputUrlImg += Date + "-" + FileName + ".png";

                page = await CreatePageAndNavigateAsync(URL);

                await page.PdfAsync(outputFile, new PdfOptions
                {
                    Format = PaperFormat.A4,
                    PrintBackground = true,
                    DisplayHeaderFooter = false
                });
                sqlResult.Result = ResultType.Successful;
                sqlResult.OutPutFile = outputFile;
                sqlResult.OutPutUrlFile = outputUrlFile;
                sqlResult.OutPutUrlImg = outputUrlImg;
                sqlResult.Message = "Html to PDF file successful.";
            }
            catch (Exception ex)
            {
                sqlResult.Message = ex.Message;
                sqlResult.Result = ResultType.Failed;
            }
            finally
            {
                if (page != null)
                {
                    try { await page.CloseAsync(); } catch { /* best-effort */ }
                }
            }
            return sqlResult;
        }

        public async Task<SqlResult> URLtoPDF(string URL, string URLParamenter = "", string CustomerName = "", string CustomerCode = "", string InvoiceNo = "")
        {
            Dictionary<string, string> rateDict = new JavaScriptSerializer().Deserialize<Dictionary<string, string>>(URLParamenter);
            string para = "";
            if (rateDict != null)
            {
                foreach (KeyValuePair<string, string> pair in rateDict)
                {
                    if (para == "")
                        para = "{" + "\"" + pair.Key + "\"" + ":" + "\"" + pair.Value + "\"";
                    else
                        para += ",\"" + pair.Key + "\"" + ":" + "\"" + pair.Value + "\"";
                }
                para += "}";
                para = "PrimaryFieldValue=" + para;
            }
            HTML html = new HTML();
            SqlResult sqlResult = new SqlResult();
            string uri = HttpContext.Current.Request.Url.GetLeftPart(UriPartial.Authority) + "/";
            IPage page = null;

            try
            {
                URL = para != "" ? uri + URL + "?" + para : uri + URL;
                CustomerName = $"{html.ToUrlSlug($"{CustomerName + " [" + CustomerCode + "]"}")}";
                string FilePath = HttpContext.Current.Server.MapPath(@"/Uploads/CustomerAttFiles/" + CustomerName + "/Invoices");
                if (!Directory.Exists(FilePath))
                    Directory.CreateDirectory(FilePath);
                InvoiceNo = $"{html.ToUrlSlug($"{InvoiceNo}")}";
                string FileName = CustomerName + "_" + InvoiceNo + ".pdf";
                string outputFile = FilePath + "\\" + FileName;

                page = await CreatePageAndNavigateAsync(URL);

                await page.PdfAsync(outputFile, new PdfOptions
                {
                    Format = PaperFormat.A4,
                    PrintBackground = true,
                    Scale = decimal.Parse("0.7")
                });

                sqlResult.Result = ResultType.Successful;
                sqlResult.Message = "Invoice to PDF file successful.";
                // no browser.Dispose() — it's the shared singleton, never dispose it here
            }
            catch (Exception ex)
            {
                sqlResult.Message = ex.Message;
                sqlResult.Result = ResultType.Failed;
                // no browser.Dispose() here either
            }
            finally
            {
                if (page != null)
                {
                    try { await page.CloseAsync(); } catch { /* best-effort */ }
                }
            }

            return sqlResult;
        }
        public async Task<SqlResult> UploadFileToServer(string FilePath, string FileName, string DestinationFolder = "/ISP_Invoice/", bool sendNotification = true, bool UploadToDMC = true)
        {
            SqlResult sqlResult = new SqlResult();
            NotificationTelegram telegram = new NotificationTelegram();

            if (!UploadToDMC) return sqlResult;

            // Consider moving these to a config file/environment variables
            string ftpHost = "192.168.69.83";
            string ftpUser = "administrator";
            string ftpPass = "Billing@12345";
            int ftpPort = 21;

            string fileFullPath = System.IO.Path.Combine(FilePath, FileName);

            //Validate local file existence BEFORE opening FTP connection
            if (!File.Exists(fileFullPath))
            {
                sqlResult.Result = ResultType.Failed;
                sqlResult.Message = $"File not found: {fileFullPath}";
                return sqlResult;
            }

            using (var client = new AsyncFtpClient(ftpHost, ftpUser, ftpPass, ftpPort))
            {
                try
                {
                    // FTP Config
                    client.Config.ValidateAnyCertificate = true;
                    client.Config.DataConnectionType = FtpDataConnectionType.PASV;

                    await client.AutoConnect();

                    // Ensure destination folder ends correctly and combine
                    string remotePath = $"{DestinationFolder.TrimEnd('/')}/{FileName}";

                    // Upload file
                    var status = FtpStatus.Failed;
                    //var status = await client.UploadFile(fileFullPath, remotePath, FtpRemoteExists.Skip, true);

                    if (status == FtpStatus.Success)
                    {
                        sqlResult.Result = ResultType.Successful;
                        sqlResult.Message = $"✅ File '{FileName}' uploaded successfully at {DateTime.Now:yyyy-MM-dd HH:mm:ss}";

                        if (sendNotification)
                        {
                            await telegram.NotificationTelegramBot("", -4510188155, "", fileFullPath, sqlResult.Message);
                        }

                        // Removed file after success
                        File.Delete(fileFullPath);
                    }
                    else if (status == FtpStatus.Skipped)
                    {
                        throw new Exception("⚠️ Upload skipped. File already exists on server.");
                    }
                    else
                    {
                        throw new Exception("❌ Upload failed. Internal FTP error.");
                    }
                }
                catch (Exception ex)
                {
                    sqlResult.Result = ResultType.Failed;
                    sqlResult.Message = $"{ex.Message}";

                    // Log error to Telegram
                    await telegram.NotificationTelegramBot("", -4510188155, "", "", sqlResult.Message);
                }
                finally
                {
                    if (client.IsConnected)
                    {
                        await client.Disconnect();
                    }
                }
            }

            return sqlResult;
        }

