        public string Pluralize(string singularForm, int howMany, string pluralForm = "s")
        {
            return (howMany == 1 || howMany == 0) ? howMany + " " + singularForm : howMany + " " + singularForm + pluralForm;
        }
        public string convertFileToBase64(string fullPathToDoc)
        {
            Byte[] bytes = System.IO.File.ReadAllBytes(fullPathToDoc);
