        }

        public string CreatePageLinks(int CurrPage, int totalRecords, int pageSize, int totalPages, int TotalNoLink = 10, string LoadGridFunction = "", string FormID = "")
        {
            int min;
            int max;
            string str;
            object[] objArray;
            if (LoadGridFunction == "") LoadGridFunction = "LoadTableGrid";
            StringBuilder strPager = new StringBuilder();
            strPager.AppendLine("<table class=\"\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">");
            strPager.AppendLine("<tfoot><tr>");
            strPager.AppendFormat("<td>Page size:</td><td>&nbsp;</td>");
            strPager.AppendLine("<td><select class=\"form-select form-select-sm\" name=\"cbopagesize\" id=\"cbopagesize" + FormID + "\">");
            strPager.AppendLine("<option value=\"10\">10</option>");
            strPager.AppendLine("<option value=\"30\">30</option>");
            strPager.AppendLine("<option value=\"50\">50</option>");
            strPager.AppendLine("<option value=\"100\">100</option>");
            strPager.AppendLine("<option value=\"0\">All</option>");
            strPager.AppendLine("</select>");
            strPager.AppendLine("</td><td>&nbsp;</td>");
            strPager.AppendFormat("<td>Page:</td><td><input class=\"form-control form-control-sm\" type=\"text\" name=\"txtpaging\" id=\"txtpaging\" style=\"color:black; height:30px; width:60px;\" value=\"{0}\" /></td><td> - {1} of {2} ", CurrPage, totalPages, totalRecords);
            strPager.AppendLine("&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>");
            if (totalRecords <= pageSize)
            {
                strPager.AppendLine("</td></tr></tfoot></table>");
                str = strPager.ToString();
            }
            else
            {
                strPager.AppendLine("<div>");
                strPager.AppendLine("<ul class=\"pagination m-0\">");
                //strPager.AppendLine("<ul id=\"icons\" class=\"ui-widget ui-helper-clearfix\">");
                int currentPage;
                if (!int.TryParse(CurrPage.ToString(), out currentPage))
                {
                    currentPage = 1;
                }
                if (currentPage > totalPages)
                {
                    currentPage = totalPages;
                }
                if (currentPage > 1)
                {
                    strPager.AppendLine("<li class=\"page-item\" title=\"First\" onclick=\"" + LoadGridFunction + "(1)\"><a href=\"javascript:void(0);\" class=\"page-link\"><i class=\"fa-solid fa-chevrons-left\"></i></a></li>");//&laquo;
                    strPager.AppendLine(string.Concat("<li class=\"page-item\" title=\"Previous\" onclick=\"" + LoadGridFunction + "(", currentPage - 2 + 1, ")\"><a href=\"javascript:void(0);\" class=\"page-link\"><i class=\"fa-solid fa-chevron-left\"></i></a></li>"));//&#8249;
                }
                if (TotalNoLink >= totalPages)
                {
                    min = 1;
                    max = totalPages;
                }
                else
                {
                    max = currentPage - (TotalNoLink / 2) <= 0 ? TotalNoLink : currentPage + (TotalNoLink / 2) - ((TotalNoLink - 1) % 2);
                    if (max > totalPages)
                    {
                        max = totalPages;
                    }
                    min = max - TotalNoLink + 1 > 0 ? max - TotalNoLink + 1 : 1;
                }
                int n = min;
                while (n <= max)
                {
                    if (n > totalPages)
                    {
                        break;
                    }
                    else
                    {
                        if (n == currentPage)
                        {
                            objArray = new object[] { "<li class=\"page-item\" style=\"color:#F60\" title=\"", n, "\"><span class=\"page-link\" style=\"color:red\">", n, "</span></li>" };
                            strPager.AppendLine(string.Concat(objArray));
                        }
                        else
                        {
                            objArray = new object[] { "<li class=\"page-item\" title=\"", n, "\" onclick=\"" + LoadGridFunction + "(", n, ")\"><a class=\"page-link\" href=\"javascript:void(0);\">", n, "</a></li>" };
                            strPager.AppendLine(string.Concat(objArray));
                        }
                        n++;
                    }
                }
                if (currentPage < totalPages)
                {
                    strPager.AppendLine(string.Concat("<li class=\"page-item\" title=\"Next\" onclick=\"" + LoadGridFunction + "(", currentPage + 1, ")\"><a class=\"page-link\" href=\"javascript:void(0);\"><i class=\"fa-solid fa-angle-right\"></i></a></li>"));//&#8250;
                    strPager.AppendLine(string.Concat("<li class=\"page-item\" title=\"Last\" onclick=\"" + LoadGridFunction + "(", totalPages, ")\"><a class=\"page-link\" href=\"javascript:void(0);\"><i class=\"fa-solid fa-angles-right\"></i></a></li>"));//&raquo;
                }
                strPager.AppendLine("</ul></div>");
                strPager.AppendLine("</td></tr></tfoot></table>");
                str = strPager.ToString();
            }
            return str;
        }
        public bool IsImageUrl(string url)
        {
            try
            {
                var client = new HttpClient();
                var response = client.SendAsync(new HttpRequestMessage(HttpMethod.Head, url));
                return response.Result.Content.Headers.ContentType.MediaType.StartsWith("image/", StringComparison.OrdinalIgnoreCase);
            }
            catch
            {
                return false;
            }
        }
        public bool IsImageValidPath(string PathImg)
        {
            try
            {
                string root = @"" + HttpContext.Current.Request.PhysicalApplicationPath.ToString();
                string fpath = root + PathImg;
                return System.IO.File.Exists(fpath);
            }
            catch
            {
                return false;
            }
        }
