            }
            catch (Exception)
            {
                result = false;
            }
            return result;
        }
        public DateTime DateTimeNow()
        {
            DateTime timeNow = DateTime.Now;
            TimeZoneInfo easternZone = TimeZoneInfo.FindSystemTimeZoneById("SE Asia Standard Time");
            return TimeZoneInfo.ConvertTime(timeNow, TimeZoneInfo.Local, easternZone);
        }

        public string DateTimeNow(string format = "")
        {
            DateTime timeNow = DateTime.Now;
            TimeZoneInfo easternZone = TimeZoneInfo.FindSystemTimeZoneById("SE Asia Standard Time");
            DateTime easternTimeNow = TimeZoneInfo.ConvertTime(timeNow, TimeZoneInfo.Local, easternZone);

            // Return formatted string directly
            return !string.IsNullOrEmpty(format) ? easternTimeNow.ToString(format) : easternTimeNow.ToString();
        }


        public SqlResult WebMarkupMin(string htmlInput)
        {
            StringBuilder sb = new StringBuilder();
            SqlResult sqlResult = new SqlResult();
            //var htmlMinifier = new HtmlMinifier();
            var settings = new HtmlMinificationSettings();
            var cssMinifier = new KristensenCssMinifier();
            var jsMinifier = new CrockfordJsMinifier();
            var logger = new NullLogger();
            var htmlMinifier = new HtmlMinifier(settings, cssMinifier,
                jsMinifier, logger);
            settings.WhitespaceMinificationMode = WhitespaceMinificationMode.Aggressive;
            settings.RemoveHtmlComments = true;
            settings.RemoveHtmlCommentsFromScriptsAndStyles = true;
            settings.MinifyEmbeddedCssCode = true;
            settings.MinifyEmbeddedJsCode = true;
            settings.MinifyEmbeddedJsonData = true;
            settings.MinifyInlineCssCode = true;
            settings.MinifyInlineJsCode = true;
            //MarkupMinificationResult result = htmlMinifier.Minify(htmlInput,
            //    fileContext: string.Empty,
            //    encoding: Encoding.GetEncoding(0),
            //    generateStatistics: false);
            MarkupMinificationResult result = htmlMinifier.Minify(htmlInput,
                generateStatistics: true);
            if (result.Errors.Count == 0)
            {
                sqlResult.Result = ResultType.Successful;
                MinificationStatistics statistics = result.Statistics;
                if (statistics != null)
                {
                    sb.AppendFormat("Original size: {0:N0} Bytes", statistics.OriginalSize);
                    sb.AppendFormat("Minified size: {0:N0} Bytes", statistics.MinifiedSize);
                    sb.AppendFormat("Saved: {0:N2}%", statistics.SavedInPercent);
                }
                sqlResult.Message = sb.ToString();
                sqlResult.Value = result.MinifiedContent;
                //MinificationStatistics statistics = result.Statistics;
                //if (statistics != null)
                //{
                //    Console.WriteLine("Original size: {0:N0} Bytes",
                //        statistics.OriginalSize);
                //    Console.WriteLine("Minified size: {0:N0} Bytes",
                //        statistics.MinifiedSize);
                //    Console.WriteLine("Saved: {0:N2}%",
                //        statistics.SavedInPercent);
                //}
                //Console.WriteLine("Minified content:{0}{0}{1}",
                //    Environment.NewLine, result.MinifiedContent);
            }
            else
            {
                IList<MinificationErrorInfo> errors = result.Errors;
                sqlResult.Result = ResultType.Failed;
                sb.AppendFormat("Found {0:N0} error(s):", errors.Count);
                //Console.WriteLine("Found {0:N0} error(s):", errors.Count);
                //Console.WriteLine();

                foreach (var error in errors)
                {
                    //Console.WriteLine("Line {0}, Column {1}: {2}",
                    //  error.LineNumber, error.ColumnNumber, error.Message);
                    //Console.WriteLine();
                    sb.AppendFormat("Line {0}, Column {1}: {2}", error.LineNumber, error.ColumnNumber, error.Message);
                }
                sqlResult.Value = sb.ToString();
            }
            return sqlResult;
        }

