            for (int j = i; j <= 2; j++)
            {
                sb.AppendLine("<tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr>");
            }
            Text = Text.Replace("{TRData}", sb.ToString());
            sb.Clear();
            ConvertToWords convertToWords = new ConvertToWords();
            sb.AppendLine("<tr><td style=\"color:white!important; background-color:#F89C39 !important\" colspan=\"2\" align=\"right\">សរុបទាំងអស់ / Grand Total</td><td style=\"color:white!important; background-color:#F89C39 !important\" align=\"right\">" + ds.Tables[0].Rows[0]["GrandTotal"] + "</td></tr>");
            sb.AppendLine("<tr><td colspan=\"2\" align=\"right\">ប្រាក់បានទទួល / Received Amount</td><td align=\"right\">" + ds.Tables[0].Rows[0]["Paid"] + "</td></tr>");
            sb.AppendLine("<tr><td colspan=\"2\" align=\"right\">សរុបទឹកប្រាក់បានបង់ / Total Paid Amount</td><td align=\"right\">" + ds.Tables[0].Rows[0]["TotalPaid"] + "</td></tr>");
            sb.AppendLine("<tr><td style=\"background-color:#eceff4 !important\" colspan=\"2\" align=\"right\">ប្រាក់នៅខ្វះ៖ / Unpaid Amount</td><td style=\"background-color:#eceff4 !important\" align=\"right\">" + ds.Tables[0].Rows[0]["Unpaid"] + "</td></tr>");
            sb.AppendLine("<tr><td align=\"right\">In Word:</td><td colspan=\"2\" align=\"center\" class=\"text-uppercase font-weight-bold text-primary\">" + convertToWords.MoneyToWords(double.Parse(ds.Tables[0].Rows[0]["Paid"].ToString())) + "</td></tr>");
            Text = Text.Replace("{TFData}", sb.ToString());
            sb.Clear();
            sql = @"select ROW_NUMBER() OVER(ORDER BY c.CustomerAccountID) as [No],
            format(c.ReceiptDate, 'dd-MM-yyyy HH:mm:ss tt') ReceiptDate,
            ca.AccountNo + ' - ' + ca.AccountName + ' (' + ca.AccountType + ')' AccountName,
            c.PaidAmount, c.[Description]
            from dbo.TblCustomerAccount c
            inner join dbo.TblChartOfAccount ca on ca.ChartOfAccountID = c.ChartOfAccountID
            where c.InvoiceNo = @InvoiceNo and format(c.ReceiptDate, 'yyMMdd HH:mm') <= @GetDate";
            Para.Clear();
            Para.Add("InvoiceNo", InvoiceNo);
            Para.Add("GetDate", ReceiptDate);
            ds = html.LoadData(sql, false, Para);

            foreach (DataRow datarow in ds.Tables[0].Rows)
            {
                sb.AppendLine("<tr>");
                sb.Append("<td>" + datarow["No"] + "</td>");
                sb.Append("<td>" + datarow["ReceiptDate"] + "</td>");
                sb.Append("<td>" + datarow["AccountName"] + "</td>");
                sb.Append("<td align=\"right\">" + datarow["PaidAmount"] + "</td>");
                sb.Append("<td>" + datarow["Description"] + "</td>");
                sb.AppendLine("</tr>");
            }
            Text = Text.Replace("{TRRelatedTransactions}", sb.ToString());

            if (GetContainerSection)
            {
                var doc = new HtmlDocument
                {
                    //OptionOutputAsXml = true,
                    //OptionCheckSyntax = true,
                    //OptionFixNestedTags = true,
                    //OptionAutoCloseOnEnd = true,
                    OptionDefaultStreamEncoding = Encoding.UTF8
                };
                doc.LoadHtml(Text.ToString());
                HtmlNode node = doc.DocumentNode.SelectNodes("//section")[0];
                sb.Clear();
                sb.Append(node.InnerHtml);
                return sb.ToString();
            }
            else
                return Text.ToString();
        }

        private static IBrowser _browser;

        private static readonly SemaphoreSlim _browserLock =
            new SemaphoreSlim(1, 1);

        // Maximum two PDF pages generating simultaneously.
        private static readonly SemaphoreSlim _pdfGenerationLock =
            new SemaphoreSlim(2, 2);

        private static readonly string[] ChromeArgs =
        {
            "--font-render-hinting=none",   // same glyph metrics on every machine
            "--force-device-scale-factor=1",
            "--disable-lcd-text",
            "--disable-gpu"
        };

        private async Task<IBrowser> GetBrowserAsync()
        {
            // 1. Reuse existing connected browser
            var current = _browser;

            if (current != null && current.IsConnected)
                return current;

            // 2. Lock browser initialization
            await _browserLock.WaitAsync();

            try
            {
                // 3. Double-check after acquiring lock
                if (_browser != null && _browser.IsConnected)
                    return _browser;

                // 4. Resolve Chromium directory
                string chromiumPath = HostingEnvironment.MapPath(
                    "~/Chromium/"
                );

                if (string.IsNullOrWhiteSpace(chromiumPath))
                {
                    throw new Exception(
                        "Chromium installation directory could not be resolved."
                    );
                }

                Directory.CreateDirectory(chromiumPath);

                // 5. Configure browser fetcher
                var fetcher = new BrowserFetcher(
                    new BrowserFetcherOptions
                    {
                        Path = chromiumPath,
                        Browser = SupportedBrowser.Chrome,
                        Platform = Platform.Win64
                    }
                );

                // 6. Find installed browser first
                InstalledBrowser installed = fetcher
                    .GetInstalledBrowsers()
                    .Where(b => !string.IsNullOrWhiteSpace(b.BuildId))
                    .OrderByDescending(b =>
                        Version.TryParse(b.BuildId, out var version)
                            ? version
                            : new Version(0, 0)
                    )
                    .FirstOrDefault();

                // 7. Download only when no browser is installed
                if (installed == null)
                {
                    System.Diagnostics.Trace.WriteLine(
                        "[CHROMIUM] No installed browser. Downloading..."
                    );

                    installed = await fetcher.DownloadAsync();
                }

                // 8. Validate executable
                string executablePath = installed.GetExecutablePath();

                if (string.IsNullOrWhiteSpace(executablePath) ||
                    !File.Exists(executablePath))
                {
                    throw new Exception(
                        "Chromium executable not found: " + executablePath
                    );
                }

                // 9. Log browser information
                try
                {
                    string logDirectory = @"C:\temp";

                    Directory.CreateDirectory(logDirectory);

                    File.AppendAllText(
                        Path.Combine(logDirectory, "browserpath.txt"),

                        $"{DateTime.Now:yyyy-MM-dd HH:mm:ss} | " +
                        $"Build: {installed.BuildId} | " +
                        $"Path: {executablePath}" +
                        Environment.NewLine
                    );
                }
                catch
                {
                    // Logging must not interrupt browser startup
                }

                // 10. Launch Chromium
                var browser = await Puppeteer.LaunchAsync(
                    new LaunchOptions
                    {
                        Headless = true,
                        ExecutablePath = executablePath,
                        Timeout = 60000,
                        Args = ChromeArgs
                    }
                );

                // 11. Handle unexpected disconnection
                browser.Disconnected += (sender, args) =>
                {
                    if (ReferenceEquals(_browser, browser))
                    {
                        _browser = null;

                        System.Diagnostics.Trace.WriteLine(
                            "[CHROMIUM] Browser disconnected."
                        );
                    }
                };

                // 12. Store shared browser
                _browser = browser;

                System.Diagnostics.Trace.WriteLine(
                    $"[CHROMIUM] Browser started successfully. " +
                    $"Build: {installed.BuildId}"
                );

                return browser;
            }
            finally
            {
                // 13. Always release initialization lock
                _browserLock.Release();
            }
        }

        private async Task<IPage> CreatePageAndNavigateAsync(
            string url,
            TimeSpan? timeout = null,
            WaitUntilNavigation[] waitUntil = null,
            bool waitForFonts = true)
        {
            IPage page = null;

            var navigationTimeout = timeout ?? TimeSpan.FromMinutes(2);

            try
            {
                // 1. Get shared browser
                var browser = await GetBrowserAsync();

                if (browser == null || !browser.IsConnected)
                    throw new Exception("Chromium browser is not connected.");

                // 2. Create isolated page
                page = await browser.NewPageAsync();

                // 3. Convert local HTML path into a file URI.
                // Preserve normal HTTP/HTTPS URLs if supplied.
                string navigationUrl = url;

                if (File.Exists(url))
                {
                    navigationUrl = new Uri(
                        Path.GetFullPath(url)
                    ).AbsoluteUri;
                }

                // 4. Navigate with an actual timeout
                await page.GoToAsync(
                    navigationUrl,
                    new NavigationOptions
                    {
                        Timeout = (int)navigationTimeout.TotalMilliseconds,

                        WaitUntil = waitUntil ?? new[]
                        {
                    WaitUntilNavigation.Load
                        }
                    }
                );

                // 5. Apply print media before PDF generation
                await page.EmulateMediaTypeAsync(MediaType.Print);

                // 6. Wait for fonts and images
                if (waitForFonts)
                {
                    await page.EvaluateExpressionAsync<string>(@"
                (async () => {

                    const waitWithTimeout = (promise, ms) => {
                        return Promise.race([
                            promise,
                            new Promise(resolve =>
                                setTimeout(resolve, ms)
                            )
                        ]);
                    };

                    // Wait for web fonts
                    if (document.fonts && document.fonts.ready) {
                        await waitWithTimeout(
                            document.fonts.ready,
                            15000
                        );
                    }

                    // Wait for images
                    const imagePromises = Array.from(
                        document.images
                    ).map(img => {

                        if (img.complete)
                            return Promise.resolve();

                        return new Promise(resolve => {

                            img.addEventListener(
                                'load',
                                resolve,
                                { once: true }
                            );

                            img.addEventListener(
                                'error',
                                resolve,
                                { once: true }
                            );
                        });
                    });

                    await waitWithTimeout(
                        Promise.all(imagePromises),
                        15000
                    );

                    return 'READY';

                })()
            ");
                }

                // 7. Log font information
                try
                {
                    string logDirectory = @"C:\temp";

                    Directory.CreateDirectory(logDirectory);

                    string info = await page.EvaluateExpressionAsync<string>(@"
                (() => {

                    const td =
                        document.querySelector('.mytable td') ||
                        document.querySelector('td');

                    if (!td)
                        return 'NO TD FOUND';

                    const cs = getComputedStyle(td);

                    return 'PRINT font=' + cs.fontFamily +
                           ' | lh=' + cs.lineHeight +
                           ' | fs=' + cs.fontSize +
                           ' | rowH=' +
                           td.getBoundingClientRect().height;

                })()
            ");

                    File.AppendAllText(
                        Path.Combine(logDirectory, "fontlog.txt"),
                        DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") +
                        " " + info + Environment.NewLine
                    );
                }
                catch (Exception ex)
                {
                    System.Diagnostics.Trace.WriteLine(
                        "[PDF FONT LOG] " + ex.Message
                    );
                }

                // 8. Return loaded page
                return page;
            }
            catch
            {
                // Close page when navigation or loading fails
                if (page != null)
                {
                    try
                    {
                        await page.CloseAsync();
                    }
                    catch
                    {
                        // Best-effort cleanup
                    }
                }

                throw;
            }
        }

        public async Task<SqlResult> HTMLToPDF(
            string HtmlData,
            string DestinationFolder,
            string FileName,
            bool ReturnUrlImg = false,
            bool AutoFileName = true,
            string pageSize = "",
            decimal Scale = 1,
            bool IsUpload = false,
            bool ShowPageNumber = false)
        {
            var result = new SqlResult
            {
                Result = ResultType.Failed
            };

            var stopwatch = System.Diagnostics.Stopwatch.StartNew();

            string tempHtmlFile = null;
            string tempPdfFile = null;
            string outputFile = null;
            string outputFileImg = null;

            IPage page = null;
            bool pdfLockAcquired = false;

            try
            {
                // 1. Validate input
                if (string.IsNullOrWhiteSpace(HtmlData))
                    throw new Exception("HTML content is empty.");

                if (string.IsNullOrWhiteSpace(FileName))
                    throw new Exception("PDF filename is empty.");

                var context = HttpContext.Current;

                if (context == null)
                    throw new Exception("HttpContext is unavailable.");

                // 2. Prepare filename
                var html = new HTML();

                if (AutoFileName)
                    FileName = html.ToUrlSlug(FileName);

                // 3. Prepare destination directory
                string relativeFolder = DestinationFolder.Trim('/', '\\');

                string filePath = context.Server.MapPath(
                    "~/" + relativeFolder
                );

                if (string.IsNullOrWhiteSpace(filePath))
                    throw new Exception("PDF destination path is invalid.");

                Directory.CreateDirectory(filePath);

                string date = DateTime.Parse(GetCurrentDate())
                    .ToString("yyyyMMdd");

                string pdfFileName = IsUpload
                    ? $"{FileName}.pdf"
                    : $"{date}-{FileName}.pdf";

                outputFile = Path.Combine(filePath, pdfFileName);

                string outputUrlFile =
                    "/" + relativeFolder.Replace('\\', '/') + "/" + pdfFileName;

                string imgFileName = $"{date}-{FileName}.png";

                outputFileImg = Path.Combine(filePath, imgFileName);

                string outputUrlImg =
                    "/" + relativeFolder.Replace('\\', '/') + "/" + imgFileName;

                // Use a unique temporary PDF to avoid incomplete output files.
                tempPdfFile = Path.Combine(
                    filePath,
                    $"{Guid.NewGuid():N}.tmp.pdf"
                );

                // 4. Prepare temporary HTML
                string tempDirectory = context.Server.MapPath("~/Uploads");

                Directory.CreateDirectory(tempDirectory);

                tempHtmlFile = Path.Combine(
                    tempDirectory,
                    $"{Guid.NewGuid():N}.html"
                );

                File.WriteAllText(
                    tempHtmlFile,
                    HtmlData,
                    System.Text.Encoding.UTF8
                );

                System.Diagnostics.Trace.WriteLine(
                    $"[HTMLToPDF] HTML prepared: {stopwatch.ElapsedMilliseconds} ms"
                );

                // 5. Limit concurrent PDF generation
                await _pdfGenerationLock.WaitAsync();
                pdfLockAcquired = true;

                // 6. Create browser page and load HTML
                page = await CreatePageAndNavigateAsync(
                    tempHtmlFile,
                    TimeSpan.FromMinutes(2),
                    null,
                    true
                );

                System.Diagnostics.Trace.WriteLine(
                    $"[HTMLToPDF] Page ready: {stopwatch.ElapsedMilliseconds} ms"
                );

                // 7. Generate screenshot if requested
                if (ReturnUrlImg)
                {
                    await page.ScreenshotAsync(
                        outputFileImg,
                        new ScreenshotOptions
                        {
                            FullPage = true
                        }
                    );

                    if (!File.Exists(outputFileImg) ||
                        new FileInfo(outputFileImg).Length == 0)
                    {
                        throw new Exception(
                            "Screenshot generation failed."
                        );
                    }
                }

                // 8. Determine paper format
                PaperFormat formatPageSize =
                    pageSize == "A3" ? PaperFormat.A3 :
                    pageSize == "A5" ? PaperFormat.A5 :
                    pageSize == "Letter" ? PaperFormat.Letter :
                    pageSize == "Legal" ? PaperFormat.Legal :
                    pageSize == "Tabloid" ? PaperFormat.Tabloid :
                    PaperFormat.A4;

                // 9. Generate PDF
                await page.PdfAsync(
                    tempPdfFile,
                    new PdfOptions
                    {
                        Format = formatPageSize,
                        PrintBackground = true,

                        DisplayHeaderFooter = ShowPageNumber,

                        HeaderTemplate = ShowPageNumber
                            ? "<span></span>"
                            : "",

                        FooterTemplate = ShowPageNumber
                            ? "<div style='width:100%; text-align:center; font-size:9px; font-family:Arial; color:#444;'>Page <span class='pageNumber'></span> of <span class='totalPages'></span></div>"
                            : "",

                        Scale = Scale,

                        MarginOptions = new MarginOptions
                        {
                            Top = "0mm",
                            Bottom = ShowPageNumber ? "15mm" : "0mm",
                            Left = "0mm",
                            Right = "5mm"
                        }
                    }
                );

                System.Diagnostics.Trace.WriteLine(
                    $"[HTMLToPDF] PDF generated: {stopwatch.ElapsedMilliseconds} ms"
                );

                // 10. Validate generated PDF
                if (!File.Exists(tempPdfFile))
                    throw new Exception("PDF output file was not created.");

                var pdfInfo = new FileInfo(tempPdfFile);

                if (pdfInfo.Length == 0)
                    throw new Exception("Generated PDF is empty.");

                // 11. Move completed PDF to final destination
                if (File.Exists(outputFile))
                {
                    File.Delete(outputFile);
                }

                File.Move(tempPdfFile, outputFile);
                tempPdfFile = null;

                // 12. Verify final output
                if (!File.Exists(outputFile))
                    throw new Exception("Final PDF file does not exist.");

                var finalPdfInfo = new FileInfo(outputFile);

                if (finalPdfInfo.Length == 0)
                    throw new Exception("Final PDF file is empty.");

                // 13. Return success
                result.Result = ResultType.Successful;
                result.OutPutFile = outputFile;
                result.OutPutUrlFile = outputUrlFile;
                result.OutPutUrlImg = outputUrlImg;
                result.Message = "Html to PDF file successful.";

                System.Diagnostics.Trace.WriteLine(
                    $"[HTMLToPDF] SUCCESS | " +
                    $"File: {outputFile} | " +
                    $"Size: {finalPdfInfo.Length} bytes | " +
                    $"Total: {stopwatch.ElapsedMilliseconds} ms"
                );
            }
            catch (Exception ex)
            {
                result.Result = ResultType.Failed;
                result.Message = "Html to PDF file failed. " + ex.ToString();

                System.Diagnostics.Trace.WriteLine(
                    $"[HTMLToPDF] ERROR: {ex}"
                );
            }
            finally
            {
                // 14. Close page
                if (page != null)
                {
                    try
                    {
                        await page.CloseAsync();
                    }
                    catch (Exception ex)
                    {
                        System.Diagnostics.Trace.WriteLine(
                            "[HTMLToPDF] Page close error: " + ex.Message
                        );
                    }
                }

                // 15. Release PDF generation lock
                if (pdfLockAcquired)
                {
                    _pdfGenerationLock.Release();
                }

                // 16. Delete temporary HTML
                if (!string.IsNullOrWhiteSpace(tempHtmlFile) &&
                    File.Exists(tempHtmlFile))
                {
                    try
                    {
                        File.Delete(tempHtmlFile);
                    }
                    catch (Exception ex)
                    {
                        System.Diagnostics.Trace.WriteLine(
                            "[HTMLToPDF] HTML cleanup error: " + ex.Message
                        );
                    }
                }

                // 17. Delete unfinished temporary PDF
                if (!string.IsNullOrWhiteSpace(tempPdfFile) &&
                    File.Exists(tempPdfFile))
                {
                    try
                    {
                        File.Delete(tempPdfFile);
                    }
                    catch (Exception ex)
                    {
                        System.Diagnostics.Trace.WriteLine(
                            "[HTMLToPDF] PDF cleanup error: " + ex.Message
                        );
                    }
                }

                stopwatch.Stop();

                System.Diagnostics.Trace.WriteLine(
                    $"[HTMLToPDF] TOTAL: {stopwatch.ElapsedMilliseconds} ms"
                );
            }

            return result;
        }

        /// <summary>
        /// Renaming Files name according to current system time
        /// </summary>
        /// <param name="dateTime"></param>
        /// <returns></returns>
        public double GetUnixTime(DateTime dateTime)
        {
            var unixTime = dateTime.ToUniversalTime() -
                           new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc);

            return unixTime.TotalSeconds;
        }
