        public string GenerateQRCode(string Data, string FName = "", string DirectoryFolder = "/Uploads/Items/QRCode")
        {
            // Generate the QR code
            QRCodeGenerator qrGenerator = new QRCodeGenerator();
            QRCodeData qrCodeData = qrGenerator.CreateQrCode(Data, QRCodeGenerator.ECCLevel.Q);
            QRCode qrCode = new QRCode(qrCodeData);
            Bitmap qrCodeImage = qrCode.GetGraphic(20);

            //// Save the QR code as a PNG image file
            //string fileName = data +"_"+ "QRCode.png";
            //qrCodeImage.Save(fileName, ImageFormat.Png);

            // Specify the folder path to save the QR code image
            string folderPath = HttpContext.Current.Server.MapPath(DirectoryFolder);

            // Create the folder if it doesn't exist
            if (!Directory.Exists(folderPath))
                Directory.CreateDirectory(folderPath);

            // Save the QR code as a PNG image file inside the specified folder
            string fileName = (FName == "" ? Guid.NewGuid().ToString() : FName) + "_" + "QRCode.png";
            qrCodeImage.Save(System.IO.Path.Combine(folderPath, fileName), ImageFormat.Png);
            return ServerRoot + DirectoryFolder + "/" + fileName;
        }
        public async Task<SqlResult> GetUserONUInfo(string SearchInfo, int key = 0, bool getContent = true, bool Reboot = false, bool Deactivate = false)
        {
            SearchInfo = HttpUtility.HtmlDecode(HttpUtility.UrlDecode(SearchInfo)).Trim();
            StringBuilder sb = new StringBuilder();
            dynamic parameters = new ExpandoObject();
            var path = HttpContext.Current.Server.MapPath(@"/Chromium/");
            SqlResult sqlResult = new SqlResult();

            var browser = await GetBrowserAsync();
            var page = await browser.NewPageAsync();

            try
            {
                string url = ""; //"https://192.168.59.69";
                string userName = ""; //"NoC";
                string password = ""; //"Noc@OLT";
                                      //await page.SetJavaScriptEnabledAsync(false);
                await page.GoToAsync(url);
                await page.TypeAsync("#user", userName);
                await page.TypeAsync("#pass", password);
                await page.ClickAsync("#loginBtn");

                //await page.ClickAsync("#menu/a/a/a");
                Thread.Sleep(1000);
                var element = await page.WaitForSelectorAsync("//div[@id=\"menu\"]/a[3]");
                await element.ClickAsync();
                Thread.Sleep(1000);
                url = url + "/action/onuauthinfo.html";
                //await page.SetJavaScriptEnabledAsync(false);
                await page.GoToAsync(url);
                var alertMessage = "";
                //attach to page during entire page life-cycle (until closed).
                //handles the case where an javscript alert comes up during login.
                page.Dialog += new EventHandler<DialogEventArgs>(async (sender, args) =>
                {
                    alertMessage = args.Dialog.Message;
                    await args.Dialog.Accept(); //this closes it..
                                                //Log.Information("Popup squashed in Login(): {0}", alertMessage);
                    Thread.Sleep(500);
                });
                Thread.Sleep(1000);
                await page.TypeAsync("#searchONU", SearchInfo);
                await page.Keyboard.PressAsync("Enter");
                Thread.Sleep(1000);
                //var pageHeaderHandle = await page.WaitForXPathAsync("//form/table[3]");
                if (alertMessage == "")
                {
                    string text = await page.GetContentAsync();
                    var doc = new HtmlDocument
                    {
                        OptionDefaultStreamEncoding = Encoding.UTF8
                    };
                    doc.LoadHtml(text.ToString());
                    if (getNode(text.ToString(), "//form/table[3]/tbody/tr[2]/td[2]") != "")
                    {
                        if (getContent)
                        {
                            HtmlNode node = doc.DocumentNode.SelectNodes("//form/table[3]/tbody/tr[2]/td[2]")[0];
                            parameters.Status = node.InnerText;
                            string Status = node.InnerText;
                            node = doc.DocumentNode.SelectNodes("//form/table[3]/tbody/tr[2]/td[1]")[0];
                            parameters.ONUID = node.InnerText;
                            string ONUID = node.InnerText;
                            node = doc.DocumentNode.SelectNodes("//form/table[3]/tbody/tr[2]/td[8]/a[2]")[0];
                            string ConnectivityStatus = node.InnerText;
                            sb.AppendLine("<div class=\"row\">");
                            sb.Append("<div class=\"col-auto\"><span class=\"badge badge-info\">" + ONUID + "</span></div>");
                            if (Status == "Offline")
                                sb.Append("<div class=\"col-auto\"><span name=\"ONUStatus\" class=\"badge badge-danger\">" + Status + "</span></div>");
                            else
                                sb.Append("<div class=\"col-auto\"><span name=\"ONUStatus\" class=\"badge badge-primary\">" + Status + "</span></div>");
                            sb.Append("<div class=\"col-auto\"><button onclick=\"DeactivateONUDevice('" + SearchInfo + "','" + key + "');\" type=\"button\" class=\"btn btn-block btn-outline-danger btn-xs\" name=\"ONUConStatus\">" + ConnectivityStatus + "</button></div>");
                            sb.Append("<div class=\"col-auto\"><button onclick=\"RebootONUDevice('" + SearchInfo + "','" + key + "');\" type=\"button\" class=\"btn btn-block btn-outline-success btn-xs\">Reboot</button></div>");
                            sb.AppendLine("</div>");
                        }
                        else if (Reboot)
                        {
                            element = await page.WaitForSelectorAsync("//form/table[3]/tbody/tr[2]/td[8]/a[7]");
                            Thread.Sleep(1000);
                            await element.ClickAsync();
                            Thread.Sleep(5000);
                            sqlResult.Message = "Device " + SearchInfo + " is rebooting.";
                            sqlResult.Result = ResultType.Successful;
                        }
                        else if (Deactivate)
                        {
                            element = await page.WaitForSelectorAsync("//form/table[3]/tbody/tr[2]/td[8]/a[2]");
                            Thread.Sleep(1000);
                            await element.ClickAsync();
                            Thread.Sleep(3000);
                            sqlResult.Message = "Device " + SearchInfo + " is deactivated.";
                            sqlResult.Result = ResultType.Successful;
                        }
                        //var pageHeaderHandle = await page.QuerySelectorAsync("h1");
                        //var innerTextHandle = await pageHeaderHandle.GetPropertyAsync("outerText");
                        //var innerText = innerTextHandle.RemoteObject.Value.ToString();
                    }
                }
            }
            catch (Exception ex)
            {
                sqlResult.Result = ResultType.Failed;
                sqlResult.Message = ex.Message;
            }
            await page.CloseAsync();
            sqlResult.Value = sb.ToString();
            return sqlResult;
        }
        public string getNode(string text, string node)
        {
            try
            {
                var doc = new HtmlDocument
                {
                    OptionDefaultStreamEncoding = Encoding.UTF8
                };
                doc.LoadHtml(text.ToString());
                if (doc.DocumentNode.SelectNodes(node) != null)
                {
                    HtmlNode nodes = doc.DocumentNode.SelectNodes(node)[0];
                    return nodes.OuterHtml;
                }
                else { return ""; }
            }
            catch (Exception)
            {
                return "";
            }
        }

        public string dataSetToJsonSt(DataSet dataDs)
        {
            int rowsCountIn = dataDs.Tables[0].Rows.Count;
            int colsCountIn = dataDs.Tables[0].Columns.Count;
            string[] columnNamesAr = new string[dataDs.Tables[0].Columns.Count];

            for (int i = 0; i < colsCountIn; i++)
            {

                columnNamesAr[i] = dataDs.Tables[0].Columns[i].ColumnName;
            }

            string jsonSt = "[";

            for (int i = 0; i < rowsCountIn; i++)
            {
                jsonSt += "{";

                for (int j = 0; j < colsCountIn; j++)
                {
                    jsonSt += (jsonSt.Substring(jsonSt.Length - 1) == "{" ? "" : ",") + "\"" + columnNamesAr[j] + "\":" + (dataDs.Tables[0].Rows[i][j] == DBNull.Value ? "null" : ("\"" + dataDs.Tables[0].Rows[i][j] + "\""));
                }

                jsonSt += "}" + (i < (rowsCountIn - 1) ? "," : "");
            }

            jsonSt += "]";

            return jsonSt;
        }

