        public Dictionary<string, string> GetUnitCal(int ItemID, int UomID, double Qty, double CostPrice)
        {
            HTML html = new HTML();
            string sql = @"
      SELECT TOP 1 *
      FROM dbo.TblItemVariant
      WHERE ItemID = @ItemID
      ORDER BY Multiplier ASC";

            var parameters = new Dictionary<string, string>
            {
                { "ItemID", ItemID.ToString() },
            };

            DataSet dataSet = html.LoadData(sql, false, parameters);

            if (dataSet.Tables[0].Rows.Count > 0)
            {
                DataRow dataRow = dataSet.Tables[0].Rows[0];

                if (dataRow["UomID"].ToString() == UomID.ToString())
                {
                    return new Dictionary<string, string>
                    {
                        { "QtyCal", Qty.ToString() },
                        { "CostPriceCal", CostPrice.ToString() }
                    };
                }
                else
                {
                    sql = @"
    SELECT TOP 1 *
    FROM dbo.TblItemVariant
    WHERE ItemID = @ItemID AND UomID = @UomID";

                    parameters.Add("UomID", UomID.ToString());

                    DataSet dataSet2 = html.LoadData(sql, false, parameters);
                    if (dataSet2.Tables[0].Rows.Count > 0)
                    {
                        DataRow dataRow2 = dataSet2.Tables[0].Rows[0];
                        double dataQty = double.Parse(dataRow["Multiplier"].ToString());
                        double dataQty2 = double.Parse(dataRow2["Multiplier"].ToString());
                        double QtyCal;
                        double CostPriceCal;
                        if (dataQty >= 1 && dataQty2 >= 1)
                        {
                            QtyCal = Qty / dataQty2;
                            CostPriceCal = CostPrice * dataQty2;

                            return new Dictionary<string, string>()
                            {
                                { "QtyCal", QtyCal.ToString() },
                                { "CostPriceCal", CostPriceCal.ToString() }
                            };
                        }
                        else
                        {
                            QtyCal = Qty * dataQty;
                            CostPriceCal = CostPrice / dataQty;

                            return new Dictionary<string, string>()
                            {
                              { "QtyCal", QtyCal.ToString() },
                              { "CostPriceCal", CostPriceCal.ToString() }
                            };
                        }
                    }
                }
            }
            return new Dictionary<string, string>
            {
                { "QtyCal", Qty.ToString() },
                { "CostPriceCal", CostPrice.ToString() }
            };
        }

        public string ConvertUnit(int ItemID, double Qty)
        {
            if (Qty > 0)
            {
                HTML html = new HTML();
                string sql = @"SELECT *
      FROM dbo.TblItemVariant
      WHERE ItemID = @ItemID
      ORDER BY Multiplier ASC";

                var parameters = new Dictionary<string, string>
                {
                  { "ItemID", ItemID.ToString() },
                };

                DataSet dataSet = html.LoadData(sql, false, parameters);
                if (dataSet.Tables[0].Rows.Count > 0)
                {
                    double qty = RoundUp(Qty, 6);
                    int i = 0, j = 0;
                    double[] QtyByUnit = new double[dataSet.Tables[0].Rows.Count]; ;
                    double Fraction = 0;
                    string QtyUnitName = "";

                    foreach (DataRow dr in dataSet.Tables[0].Rows)
                    {
                        QtyByUnit[i] = double.Parse(dr["Multiplier"].ToString());
                        double Whole;
                        if (i > 0)
                        {
                            qty = RoundUp(Fraction * QtyByUnit[i], 8);
                            //Whole = (int)Math.Floor(qty);
                            Whole = Math.Round(qty, 2);
                            Fraction = Fraction - (Whole / QtyByUnit[i]);
                        }
                        else
                        {
                            Whole = (int)Math.Floor(qty);
                            Fraction = qty - Whole;
                        }

                        if (Whole > 0)
                        {
                            QtyUnitName += (j > 0 ? " & " : "") + Whole + "" + " (" + dr["UM"] + ") ";
                            j++;
                        }

                        i++;
                    }

                    return QtyUnitName;

                }
            }
            return Qty.ToString();
        }

        public static double RoundUp(double number, int decimalPlaces)
        {
            double multiplier = Math.Pow(10, decimalPlaces);
            return Math.Ceiling(number * multiplier) / multiplier;
        }

