            ;
        }

        public string CorrectKhmerAddress(string address)
        {
            // Step 1: Remove any leading or misplaced Unicode characters before Khmer text
            address = Regex.Replace(address, @"^[^\p{L}]*", ""); // Remove non-letter characters from the start

            // Step 2: Replace double commas with a single comma and ensure proper spacing after punctuation
            address = Regex.Replace(address, @"\s*,\s*,", ", "); // Remove double commas
            address = Regex.Replace(address, @"\s*,\s*", ", ");  // Ensure single space after commas
            address = Regex.Replace(address, @"\s*៖ុ\s*", "៖ "); // Khmer colon correction
            address = Regex.Replace(address, @"(\p{L})(\d)", "$1 $2"); // Add space between Khmer letters and numbers
            address = Regex.Replace(address, @"(\d)(\p{L})", "$1 $2"); // Add space between numbers and letters

            // Step 3: Handle misplaced Khmer-specific punctuation and characters
            address = Regex.Replace(address, @"\s*។\s*", "។ ");   // Ensure single space after "។"
            address = Regex.Replace(address, @"\s*៖\s*", "៖ ");   // Ensure single space after "៖"

            // Step 4: Trim spaces around the entire address and remove excess spaces between words
            address = address.Trim();                             // Trim any leading or trailing spaces
            address = Regex.Replace(address, @"\s{2,}", " ");     // Remove extra spaces between words

            // Step 5: Fix specific common mistakes (for example, space after "ផ្ទះលេខ")
            address = Regex.Replace(address, @"ផ្ទះលេខ\s*(\w+)", "ផ្ទះលេខ $1");

            return address;
        }

        public string GetBotTokenBySystemID(int systemID)
        {
            string token = "";
            try
            {
                HTML html = new HTML();
                DataSet ds = new DataSet();
                Dictionary<string, string> para = new Dictionary<string, string>
                {
                    { "SystemID", systemID.ToString() }
                };
                string sql = @"select top 1 BotToken from dbo.TblTelegramBots
                        where SystemID = @SystemID and IsActive = 1
                        order by CreateDate desc";
                ds = html.LoadData(sql, false, para);
                if (ds.Tables.Count > 0 && ds.Tables[0].Rows.Count > 0)
                {
                    token = ds.Tables[0].Rows[0]["BotToken"].ToString();
                }
            }
            catch (Exception ex)
            {
                throw new Exception(ex.Message, ex);
            }
            return token;
        }
